import subprocess, pathlib, shutil, os, stat
exe="/workspace/executable"
def setup():
 d=pathlib.Path("/tmp/filetypes"); shutil.rmtree(d,ignore_errors=True); d.mkdir(parents=True)
 (d/"reg.txt").write_bytes(b"hello\n"*10)
 (d/"dir").mkdir(); (d/"dir/f.txt").write_bytes(b"infdir\n")
 os.symlink("reg.txt",d/"link.txt")
 os.symlink("nonexistent",d/"badlink")
 os.symlink("dir",d/"linkdir")
 os.mkfifo(d/"fifo")
 (d/"noperm").write_bytes(b"secret\n"); os.chmod(d/"noperm",0)
 return d
def run(args,stdin=b""):
 d=setup()
 p=subprocess.run([exe]+args,cwd=d,input=stdin,capture_output=True,timeout=5)
 files=[]
 for x in sorted(d.rglob("*")):
  if x.is_fifo(): files.append((str(x.relative_to(d)),"fifo"))
  elif x.is_file() or x.is_symlink(): files.append((str(x.relative_to(d)), x.lstat().st_size if not x.is_dir() else "dir"))
 print(args,p.returncode,p.stderr,p.stdout[:60],files)
for f in ["reg.txt","dir","link.txt","badlink","linkdir","noperm","fifo","/dev/null","/dev/zero","/dev/stdin","/proc/self/cmdline"]:
 try: run([f],stdin=b"stdin data\n" if f=="/dev/stdin" else b"")
 except Exception as e: print(f,e)
for f in ["dir","link.txt","fifo"]:
 try: run(["-f",f])
 except Exception as e: print("force",f,e)
run(["-r","dir"])
run(["-r","."])
PY
"}

