import pty, os, subprocess, time, pathlib
exe="/workspace/executable"
def run(args, stdin_mode="pipe", stdout_mode="tty", stderr_mode="pipe", input_data=b"hello\n"):
    fds=[]
    def make(mode):
        if mode=="tty":
            m,s=pty.openpty(); fds.append(m); return s,m
        return subprocess.PIPE,None
    # Use Popen manually
    masters={}
    kwargs={}
    if stdin_mode=="tty":
        m,s=pty.openpty(); masters['in']=m; kwargs['stdin']=s
    else: kwargs['stdin']=subprocess.PIPE
    if stdout_mode=="tty":
        m,s=pty.openpty(); masters['out']=m; kwargs['stdout']=s
    else: kwargs['stdout']=subprocess.PIPE
    if stderr_mode=="tty":
        m,s=pty.openpty(); masters['err']=m; kwargs['stderr']=s
    else: kwargs['stderr']=subprocess.PIPE
    p=subprocess.Popen([exe]+args,**kwargs)
    # close slave fds in parent? Popen duplicated; the s variables lost? Our kwargs values are ints, close them
    for k,v in list(kwargs.items()):
        if isinstance(v,int): os.close(v)
    if stdin_mode!="tty":
        try: p.stdin.write(input_data); p.stdin.close()
        except Exception: pass
    else:
        if input_data: os.write(masters['in'],input_data); os.write(masters['in'],b"\x04")
    # collect
    out=b""; err=b""
    for name,m in masters.items():
        os.set_blocking(m,False)
    start=time.time()
    while time.time()-start<2:
        for name,m in masters.items():
            try:
                c=os.read(m,4096)
                if c:
                    if name=='out': out+=c
                    elif name=='err': err+=c
            except Exception: pass
        if p.poll() is not None: break
        time.sleep(0.02)
    if p.poll() is None: p.kill(); rc="timeout"
    else: rc=p.returncode
    if stdout_mode!="tty" and p.stdout: 
        try: out+=p.stdout.read() or b""
        except: pass
    if stderr_mode!="tty" and p.stderr:
        try: err+=p.stderr.read() or b""
        except: pass
    for m in masters.values():
        try: os.close(m)
        except: pass
    print("args",args,"stdin",stdin_mode,"stdout",stdout_mode,"stderr",stderr_mode,"rc",rc,"OUT",out[:300],"ERR",err[:500])
pathlib.Path("/tmp/ptyb.txt").write_bytes(b"hello out\n"*10); subprocess.run([exe,"-fq","/tmp/ptyb.txt"])
run(["/tmp/ptyb.txt"],stdout_mode="tty",stderr_mode="pipe")
run(["-c","/tmp/ptyb.txt"],stdout_mode="tty")
