        mv = memoryview(data)
        while mv:
            n = os.write(2, mv)
            if n <= 0:
                break
            mv = mv[n:]
    except OSError:
        pass

class StdoutWriter:
    def __init__(self):
        self.buf = bytearray()
    def write(self, data):
        if isinstance(data, str):
            data = fsb(data)
        if not data:
            return
        # write directly; stdout for binary data must not be reordered
        mv = memoryview(bytes(data))
        while mv:
            n = os.write(1, mv)
            mv = mv[n:]
    def flush(self):
        pass

STDOUT = StdoutWriter()

def owrite(data):
    STDOUT.write(data)

class StdinBuffer:
    """Shared buffered reader for fd 0, used for stdin input, prompts and -p."""
    def __init__(self):
        self.buf = bytearray()
        self.eof = False
        self.used_as_input = False
    def _fill(self, want=65536):
        if self.eof:
            return False
        try:
            chunk = os.read(0, max(1, want))
        except OSError:
            chunk = b""
        if not chunk:
            self.eof = True
            return False
        self.buf += chunk
        return True
    def read(self, n):
        self.used_as_input = True
        if n <= 0:
            return b""
        while len(self.buf) < n and not self.eof:
            if not self._fill(max(65536, n - len(self.buf))):
                break
        out = bytes(self.buf[:n])
        del self.buf[:n]
        return out
    def read1(self):
        if not self.buf and not self.eof:
            self._fill(1)
        if not self.buf:
            return b""
        out = bytes(self.buf[:1])
        del self.buf[:1]
        return out
    def read_line_first_char(self):
        """Read one line worth of input (discard rest of line); return first byte or b''."""
        first = self.read1()
        if first == b"":
            return b""
        if first == b"\n":
            return first
        # drain until newline or eof
        while True:
            c = self.read1()
            if c in (b"", b"\n"):
                break
        return first

STDIN = StdinBuffer()

