class TraceManager:
    HEADER = ("Algorithm, Version, Method, Mode, Level, Workers, Dictionary Size, "
              "Uncompressed Size, Compressed Size, Duration Nanos, Compression Ratio, Speed MB/s\n")
    def __init__(self):
        self.fh = None
        self.enabled = False
    def enable(self, filename):
        self.close()
        self.enabled = True
        try:
            # append mode; header only if file is empty / newly created
            fh = open(filename, "ab+", buffering=0)
            fh.seek(0, os.SEEK_END)
            if fh.tell() == 0:
                fh.write(self.HEADER.encode())
            self.fh = fh
        except OSError:
            self.fh = None
    def log(self, method, mode, level, workers, dict_size, src_size, dst_size, duration_ns):
        if not self.enabled or self.fh is None:
            return
        if src_size and src_size > 0:
            ratio = src_size / dst_size if dst_size else 0.0
            # Original ratio field is uncompressed/compressed for both directions.
            ratio_val = ratio
        else:
            ratio_val = 0.0
        speed = (src_size / duration_ns * 1000.0) if duration_ns else 0.0
        line = (f"zstd, {VERSION_NUMBER_INT}, {method}, {mode}, {int(level)}, {int(workers)}, "
                f"{int(dict_size)}, {int(src_size)}, {int(dst_size)}, {int(duration_ns)}, "
                f"{ratio_val:.2f}, {speed:.2f}\n")
        try:
            self.fh.write(line.encode())
        except OSError:
            pass
    def close(self):
        if self.fh is not None:
            try:
                self.fh.close()
            except Exception:
                pass
            self.fh = None

TRACE = TraceManager()

def human_size_parts(size):
    """Return (number_string, suffix) using the CLI's odd precision rules."""
    size = int(size)
    if size < 1024:
        return (str(size), "B")
    suffixes = ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB"]
    unit = 1024
    idx = 0
    while size >= unit * 1024 and idx < len(suffixes) - 1:
        unit *= 1024
        idx += 1
    value = size / unit
    if size == unit:
        # observed special case: exactly one unit prints with 3 decimals
        num = f"{value:.3f}"
    elif value < 10:
        num = f"{value:.2f}"
    elif value < 100:
        num = f"{value:.1f}"
    else:
        num = f"{value:.0f}"
    return (num, suffixes[idx])

def human_size(size, padded_number_width=0, padded_suffix=False):
    num, suf = human_size_parts(size)
    if padded_number_width:
        num = num.rjust(padded_number_width)
    if padded_suffix:
        suf = suf.rjust(3)
    return f"{num} {suf}"

def signed32(value):
    value = int(value) & 0xFFFFFFFF
    if value >= 0x80000000:
        value -= 0x100000000
    return value

def parse_env_values():
    """Parse ZSTD_CLEVEL / ZSTD_NBTHREADS, printing warnings unconditionally."""
    clevel = None
    nbthreads = None
    raw = os.environ.get("ZSTD_CLEVEL")
    if raw is not None:
        ok, val, too_large = _parse_env_signed(raw)
        if too_large:
            ewrite(f"Ignore environment variable setting ZSTD_CLEVEL={raw}: numeric value too large \n")
        elif not ok:
            ewrite(f"Ignore environment variable setting ZSTD_CLEVEL={raw}: not a valid integer value \n")
        else:
            clevel = val
    raw = os.environ.get("ZSTD_NBTHREADS")
    if raw is not None:
        ok, val, too_large = _parse_env_unsigned(raw)
        if too_large:
            ewrite(f"Ignore environment variable setting ZSTD_NBTHREADS={raw}: numeric value too large \n")
        elif not ok:
            ewrite(f"Ignore environment variable setting ZSTD_NBTHREADS={raw}: not a valid unsigned value \n")
        else:
            nbthreads = val
    return clevel, nbthreads

def _parse_env_signed(raw):
    s = raw
    if not s:
        return (False, 0, False)
    sign = 1
    i = 0
    if s[0] in "+-":
        if s[0] == "-":
            sign = -1
        i = 1
    if i >= len(s) or not s[i:].isdigit() or not s[i:].isascii():
        return (False, 0, False)
    # ascii digits only
    if any(c < "0" or c > "9" for c in s[i:]):
        return (False, 0, False)
    val = int(s[i:])
    if val > UINT_MAX:
        return (False, 0, True)
    return (True, signed32(sign * val), False)

def _parse_env_unsigned(raw):
    s = raw
    if not s or any(c < "0" or c > "9" for c in s):
        return (False, 0, False)
    val = int(s)
    if val > UINT_MAX:
        return (False, 0, True)
    return (True, val, False)

def warn_env_nbthreads_if_invalid(display_ok):
    """Second parse inside file-io: warn again if env invalid and display allows."""
    if not display_ok:
        return
    raw = os.environ.get("ZSTD_NBTHREADS")
    if raw is None:
        return
    ok, val, too_large = _parse_env_unsigned(raw)
    if too_large:
        ewrite(f"Ignore environment variable setting ZSTD_NBTHREADS={raw}: numeric value too large \n")
    elif not ok:
        ewrite(f"Ignore environment variable setting ZSTD_NBTHREADS={raw}: not a valid unsigned value \n")

def core_count(logical):
    try:
        logical_count = len(os.sched_getaffinity(0))
    except Exception:
        logical_count = os.cpu_count() or 1
    if logical:
        return logical_count or 1
    # physical cores: parse /proc/cpuinfo "cpu cores" * physical packages,
    # restricted to affinity set if possible via topology files.
    try:
        # Try sysfs topology for CPUs in affinity set.
        try:
            cpus = sorted(os.sched_getaffinity(0))
        except Exception:
            cpus = list(range(logical_count))
        cores = set()
        ok = True
        for cpu in cpus:
            base = f"/sys/devices/system/cpu/cpu{cpu}/topology"
            try:
                with open(os.path.join(base, "physical_package_id")) as fh:
                    pkg = fh.read().strip()
                with open(os.path.join(base, "core_id")) as fh:
                    cid = fh.read().strip()
                cores.add((pkg, cid))
            except OSError:
                ok = False
                break
        if ok and cores:
            return len(cores)
    except Exception:
        pass
    try:
        cores_per_pkg = None
        packages = set()
        cur_pkg = None
        with open("/proc/cpuinfo") as fh:
            for line in fh:
                if line.startswith("physical id"):
                    cur_pkg = line.split(":", 1)[1].strip()
                    packages.add(cur_pkg)
                elif line.startswith("cpu cores"):
                    cores_per_pkg = int(line.split(":", 1)[1].strip())
        if cores_per_pkg:
            n = cores_per_pkg * max(1, len(packages))
            return min(n, logical_count) if logical_count else n
    except Exception:
        pass
    return logical_count or 1

