class ArgParser:
    def __init__(self, argv):
        self.argv = argv
        self.i = 0
        self.filenames_only = False

    def next_arg_string(self):
        """Consume next argv as an option argument (C readStringFromArgv)."""
        if self.i + 1 >= len(self.argv):
            err_exit("error: missing command argument \n", 1)
        nxt = self.argv[self.i + 1]
        if len(nxt) > 0 and nxt[0] == "-":
            err_exit("error: command cannot be separated from its argument by another command \n", 1)
        self.i += 1
        return nxt

    def parse(self):
        while self.i < len(self.argv):
            arg = self.argv[self.i]
            if self.filenames_only:
                ST.filenames.append(InputName(arg, False))
                self.i += 1
                continue
            if arg == "--":
                self.filenames_only = True
                self.i += 1
                continue
            if arg == "-":
                ST.filenames.append(InputName(STDIN_MARK, True))
                self.i += 1
                continue
            if arg.startswith("--"):
                self.parse_long(arg)
                self.i += 1
                continue
            if arg.startswith("-") and len(arg) > 1:
                self.parse_short(arg)
                self.i += 1
                continue
            ST.filenames.append(InputName(arg, False))
            self.i += 1

    # ---- generic parameter-string parsing (key=value,key=value) ----
    def parse_param_segments(self, original_arg, param_str, keymap, allow_bare=None, signed=False, target=None):
        """keymap: dict key->field name. allow_bare: set of keys usable without '='.
        Returns dict field->value."""
        if target is None:
            target = {}
        if allow_bare is None:
            allow_bare = set()
        s = param_str
        pos = 0
        if s == "":
            bad_usage(original_arg)
        while pos < len(s):
            matched = None
            # find key at pos: key is up to '=' or ',' or end
            j = pos
            while j < len(s) and s[j] not in "=,":
                j += 1
            key = s[pos:j]
            if key not in keymap:
                bad_usage(original_arg)
            field = keymap[key]
            if j < len(s) and s[j] == "=":
                j += 1
                try:
                    if signed:
                        value, j = self._read_signed(s, j, original_arg)
                    else:
                        value, j = read_u32_checked_suffix(s, j, 32)
                except _NumOverflow as exc:
                    if signed:
                        err_exit("error: numeric value overflows 32-bit int \n", 1)
                    err_exit("error: numeric value overflows 32-bit unsigned int \n", 1)
                target[field] = value
            else:
                if key not in allow_bare:
                    bad_usage(original_arg)
                target[field] = 1
            if j < len(s):
                if s[j] == ",":
                    j += 1
                    if j >= len(s):
                        bad_usage(original_arg)
                else:
                    bad_usage(original_arg)
            pos = j
        return target

    def _read_signed(self, s, pos, original_arg):
        sign = 1
        i = pos
        if i < len(s) and s[i] == "-":
            sign = -1
            i += 1
        value, i2 = read_u32_checked_suffix(s, i, 32)
        return signed32(sign * value), i2

    # ---- long options ----
    def long_value(self, arg, prefix):
        rest = arg[len(prefix):]
        if rest.startswith("="):
            return rest[1:]
        return self.next_arg_string()

    def parse_long(self, arg):
        st = ST
