        warg_string = ["--trace", "--filelist", "--output-dir-flat", "--output-dir-mirror",
                       "--patch-from", "--patch-apply", "--auto-threads"]
        warg_u32 = ["--threads", "--memory", "--memlimit", "--maxdict", "--dictID"]
        warg_size = ["--jobsize", "--split", "--block-size", "--stream-size",
                     "--size-hint", "--target-compressed-block-size"]
        for prefix in warg_string:
            if arg.startswith(prefix):
                val = self.long_value(arg, prefix)
                self.apply_string_arg(prefix, val)
                return
        for prefix in warg_u32:
