                    st.train_algo = "cover"
                    self.parse_param_segments(arg, params,
                        {"k": "k", "d": "d", "steps": "steps", "split": "split", "shrink": "shrink"},
                        allow_bare={"shrink"}, target=st.cover_params)
                elif algo == "fastcover_opt":
                    st.train_algo = "fastcover"
                    self.parse_param_segments(arg, params,
                        {"k": "k", "d": "d", "f": "f", "steps": "steps", "split": "split",
                         "accel": "accel", "shrink": "shrink"},
                        allow_bare={"shrink"}, target=st.fastcover_params)
                else:
                    vals = self.parse_param_segments(arg, params,
                        {"s": "s", "selectivity": "s"})
                    if "s" in vals:
                        st.dict_selectivity = vals["s"]
                return
        # --fast / --long / --adapt with optional =value
        if arg == "--fast" or arg.startswith("--fast="):
            if arg == "--fast":
                st.clevel = -1
            else:
                vstr = arg[len("--fast="):]
                try:
                    value, _pos = read_u32_checked_suffix(vstr, 0, 32)
                except _NumOverflow:
                    err_exit("error: numeric value overflows 32-bit unsigned int \n", 1)
                if value == 0:
                    bad_usage(arg)
                st.clevel = signed32(-value)
            return
        if arg == "--long" or arg.startswith("--long="):
            if arg == "--long":
                value = 27
            else:
                vstr = arg[len("--long="):]
                try:
                    value, _pos = read_u32_checked_suffix(vstr, 0, 32)
                except _NumOverflow:
                    err_exit("error: numeric value overflows 32-bit unsigned int \n", 1)
            st.ldm_enabled = True
            if st.cparams.get("windowLog", 0) == 0:
                st.cparams["windowLog"] = value
            return
        if arg == "--adapt" or arg.startswith("--adapt="):
            st.adapt = True
            if arg != "--adapt":
                params = arg[len("--adapt="):]
                vals = self.parse_param_segments(arg, params, {"min": "min", "max": "max"}, signed=True)
                if "min" in vals:
                    st.adapt_min = vals["min"]
                if "max" in vals:
                    st.adapt_max = vals["max"]
            return
        # options taking a string / numeric argument (prefix-matched, C style)
        warg_string = ["--trace", "--filelist", "--output-dir-flat", "--output-dir-mirror",
                       "--patch-from", "--patch-apply", "--auto-threads"]
        warg_u32 = ["--threads", "--memory", "--memlimit", "--maxdict", "--dictID"]
        warg_size = ["--jobsize", "--split", "--block-size", "--stream-size",
                     "--size-hint", "--target-compressed-block-size"]
        for prefix in warg_string:
            if arg.startswith(prefix):
                val = self.long_value(arg, prefix)
                self.apply_string_arg(prefix, val)
                return
        for prefix in warg_u32:
            if arg.startswith(prefix):
                val = self.long_value(arg, prefix)
                num = checked_number_or_exit(val, 32)
                self.apply_u32_arg(prefix, num)
                return
        for prefix in warg_size:
            if arg.startswith(prefix):
                val = self.long_value(arg, prefix)
                num = checked_number_or_exit(val, 64)
                self.apply_size_arg(prefix, num)
                return
        # exact no-argument long options
        exact = {
            "--compress": "compress", "--decompress": "decompress",
            "--uncompress": "decompress", "--test": "test", "--list": "list",
            "--stdout": "stdout", "--force": "force", "--keep": "keep", "--rm": "rm",
            "--verbose": "verbose", "--quiet": "quiet",
            "--single-thread": "single_thread",
            "--sparse": "sparse", "--no-sparse": "no_sparse",
            "--pass-through": "pass_through", "--no-pass-through": "no_pass_through",
            "--check": "check", "--no-check": "no_check",
            "--progress": "progress", "--no-progress": "no_progress",
            "--asyncio": "asyncio", "--no-asyncio": "no_asyncio",
            "--ultra": "ultra", "--rsyncable": "rsyncable",
            "--exclude-compressed": "exclude_compressed",
            "--no-dictID": "no_dict_id",
            "--compress-literals": "compress_literals",
            "--no-compress-literals": "no_compress_literals",
            "--row-match-finder": "row_match", "--no-row-match-finder": "no_row_match",
            "--mmap-dict": "mmap_dict", "--no-mmap-dict": "no_mmap_dict",
            "--content-size": "content_size", "--no-content-size": "no_content_size",
            "--show-default-cparams": "show_cparams",
            "--train": "train",
        }
        if arg in exact:
            self.apply_exact(exact[arg])
            return
        bad_usage(arg)

    def apply_string_arg(self, prefix, val):
        st = ST
        if prefix == "--trace":
            TRACE.enable(val)
        elif prefix == "--filelist":
            st.filelists.append(val)
        elif prefix == "--output-dir-flat":
            if val == "":
                err_exit("error: output dir cannot be empty string (did you mean to pass '.' instead?)\n", 1)
            st.output_dir_flat = val
        elif prefix == "--output-dir-mirror":
            if val == "":
                err_exit("error: output dir cannot be empty string (did you mean to pass '.' instead?)\n", 1)
            st.output_dir_mirror = val
        elif prefix == "--patch-from":
            st.patch_from = val
        elif prefix == "--patch-apply":
            st.patch_from = val
            st.operation = "decompress"
        elif prefix == "--auto-threads":
            st.auto_threads_logical = (val == "logical")

    def apply_u32_arg(self, prefix, num):
        st = ST
        if prefix == "--threads":
            st.nb_threads = signed32(num)
            st.single_thread = False
        elif prefix in ("--memory", "--memlimit"):
            st.mem_limit = num
        elif prefix == "--maxdict":
            st.dict_max_size = num
        elif prefix == "--dictID":
            st.dict_id_force = num

    def apply_size_arg(self, prefix, num):
        st = ST
        if prefix in ("--jobsize", "--split", "--block-size"):
            st.block_size = num
        elif prefix == "--stream-size":
            st.stream_size = num
        elif prefix == "--size-hint":
            st.size_hint = num
        elif prefix == "--target-compressed-block-size":
            st.target_cblock_size = num

    def apply_exact(self, kind):
        st = ST
        if kind == "compress":
            st.operation = "compress"
        elif kind == "decompress":
            st.operation = "decompress"
        elif kind == "test":
            st.operation = "test"
        elif kind == "list":
            st.operation = "list"
        elif kind == "train":
            st.operation = "train"
            st.train_algo = "fastcover_opt"
            if st.output_file is None:
                st.output_file = "dictionary"
        elif kind == "stdout":
            st.output_file = STDOUT_MARK
            st.stdout_explicit = True
        elif kind == "force":
            st.force = True
        elif kind == "keep":
            st.remove_src = False
        elif kind == "rm":
            st.remove_src = True
        elif kind == "verbose":
            st.display_level += 1
        elif kind == "quiet":
            st.display_level -= 1
        elif kind == "single_thread":
            st.nb_threads = 0
            st.single_thread = True
        elif kind == "sparse":
            st.sparse_setting = 1
        elif kind == "no_sparse":
            st.sparse_setting = 0
        elif kind == "pass_through":
            st.pass_through_setting = True
        elif kind == "no_pass_through":
            st.pass_through_setting = False
        elif kind == "check":
            st.checksum_flag = 2
        elif kind == "no_check":
            st.checksum_flag = 0
        elif kind == "progress":
            st.progress_setting = True
        elif kind == "no_progress":
            st.progress_setting = False
        elif kind == "asyncio":
            st.asyncio_enabled = True
        elif kind == "no_asyncio":
            st.asyncio_enabled = False
        elif kind == "ultra":
            st.ultra = True
        elif kind == "rsyncable":
            st.rsyncable = True
        elif kind == "exclude_compressed":
            st.exclude_compressed = True
        elif kind == "no_dict_id":
            st.dict_id = False
        elif kind == "compress_literals":
            st.compress_literals = True
        elif kind == "no_compress_literals":
            st.compress_literals = False
        elif kind == "row_match":
            st.row_match_finder = True
        elif kind == "no_row_match":
            st.row_match_finder = False
        elif kind == "mmap_dict":
            st.mmap_dict = True
        elif kind == "no_mmap_dict":
            st.mmap_dict = False
        elif kind == "content_size":
            st.content_size = True
        elif kind == "no_content_size":
            st.content_size = False
        elif kind == "show_cparams":
            st.show_default_cparams = True

    # ---- short options ----
    def parse_short(self, arg):
        st = ST
        pos = 1
        L = len(arg)
        while pos < L:
            ch = arg[pos]
            if "0" <= ch <= "9":
                value, pos = parse_cluster_u32(arg, pos)
                st.clevel = signed32(value)
                continue
            if ch == "h":
                print_help(False)
                raise ExitMain(0)
            if ch == "H":
                print_help(True)
                raise ExitMain(0)
            if ch == "V":
                print_version()
                raise ExitMain(0)
            if ch in ("o", "D"):
                # string argument: '=value' finishes the cluster,
                # otherwise the next argv is consumed and the cluster continues.
                if pos + 1 < L and arg[pos + 1] == "=":
                    value = arg[pos + 2:]
                    pos = L
                else:
                    value = self.next_arg_string()
                    pos += 1
                if ch == "o":
                    st.output_file = value
                    st.stdout_explicit = False
                else:
                    st.dict_file = value
                continue
            if ch in ("e", "i", "M", "T", "B", "s", "P"):
                value, pos = parse_cluster_u32(arg, pos + 1)
                if ch == "e":
                    st.bench_end_level = value
                elif ch == "i":
                    st.bench_seconds = value
                elif ch == "M":
                    st.mem_limit = value
                elif ch == "T":
                    st.nb_threads = signed32(value)
                    st.single_thread = False
                elif ch == "B":
                    st.block_size = value
                elif ch == "s":
                    st.dict_selectivity = value
                elif ch == "P":
                    st.compressibility = value
                continue
            # boolean letters
            pos += 1
            if ch == "b":
                st.operation = "bench"
            elif ch == "c":
                st.output_file = STDOUT_MARK
                st.stdout_explicit = True
            elif ch == "d":
                st.bench_decompress_only = True
                if st.operation != "bench":
                    st.operation = "decompress"
            elif ch == "f":
                st.force = True
            elif ch == "k":
                st.remove_src = False
            elif ch == "l":
                st.operation = "list"
            elif ch == "n":
                pass  # gzip --no-name compatibility: no effect
            elif ch == "p":
                st.pause = True
            elif ch == "q":
                st.display_level -= 1
            elif ch == "r":
                st.recursive = True
            elif ch == "t":
                st.operation = "test"
            elif ch == "v":
                st.display_level += 1
            elif ch == "z":
                st.operation = "compress"
            elif ch == "C":
                st.checksum_flag = 2
            elif ch == "S":
                st.bench_separate = True
            else:
                bad_usage(f"-{ch}")

