def check_and_open_src(item):
    """Returns SrcInfo or None (error already reported)."""
    info = SrcInfo(item)
    if item.is_stdin:
        return info
    path = item.text
    # symlink check first (with FIFO-target bypass observed in the reference)
    try:
        lst = os.lstat(path)
        is_link = stat_mod.S_ISLNK(lst.st_mode)
    except OSError:
        is_link = False
        lst = None
    if is_link and not ST.force:
        # bypass if link target is a FIFO (e.g. /dev/stdin pointing at a pipe)
        bypass = False
        try:
            tgt = os.stat(path)
            if stat_mod.S_ISFIFO(tgt.st_mode):
                bypass = True
        except OSError:
            pass
        if not bypass:
            disp(2, f"Warning : {path} is a symbolic link, ignoring \n")
            return None
    try:
        st = os.stat(path)
    except OSError as exc:
        disp(1, f"zstd: can't stat {path} : {exc.strerror or str(exc)} -- ignored \n")
        return None
    if stat_mod.S_ISDIR(st.st_mode):
        disp(1, f"zstd: {path} is a directory -- ignored \n")
        return None
    if not (stat_mod.S_ISREG(st.st_mode) or stat_mod.S_ISFIFO(st.st_mode)):
        disp(1, f"zstd: {path} is not a regular file -- ignored \n")
        return None
    info.stat = st
    info.size = st.st_size if stat_mod.S_ISREG(st.st_mode) else None
    # open now (before any destination handling)
    try:
        fd = os.open(path, os.O_RDONLY)
    except OSError as exc:
        disp(1, f"zstd: {path}: {exc.strerror or str(exc)} \n")
        return None
    info.fd = fd
    info.fh = os.fdopen(os.dup(fd), "rb", buffering=0)
    os.close(fd)
    info.fd = info.fh.fileno()
    return info

