class DstWriter:
    """Output sink: stdout, a regular file, or /dev/null-like test sink."""
    def __init__(self, kind, fd=None, path=None, sparse=False):
        self.kind = kind    # 'stdout' | 'file' | 'sink'
        self.fd = fd
        self.path = path
        self.sparse = sparse
        self.total = 0
        self._sparse_pending = 0
        self._sparse_buf = bytearray()
        self._sparse_pos_in_segment = 0
        self.write_error = None
    def write(self, data):
        if not data:
            return True
        self.total += len(data)
        if self.kind == "sink":
            return True
        if self.kind == "stdout":
            try:
                mv = memoryview(bytes(data))
                while mv:
                    n = os.write(1, mv)
                    mv = mv[n:]
                return True
            except OSError as exc:
                self.write_error = exc
                return False
        # file
        if self.sparse:
            return self._write_sparse_feed(data)
        try:
            mv = memoryview(bytes(data))
            while mv:
                n = os.write(self.fd, mv)
                mv = mv[n:]
            return True
        except OSError as exc:
            self.write_error = exc
            return False
    # sparse handling: process in 32 KiB segments
    def _write_sparse_feed(self, data):
        self._sparse_buf += bytes(data)
        while len(self._sparse_buf) >= 32768:
            chunk = bytes(self._sparse_buf[:32768])
            del self._sparse_buf[:32768]
            if not self._write_sparse_segment(chunk):
                return False
        return True
    def _write_sparse_segment(self, chunk):
        if not any(chunk):
            self._sparse_pending += len(chunk)
            return True
        # find first nonzero
        first = 0
        nb = len(chunk)
        while first < nb and chunk[first] == 0:
            first += 1
        self._sparse_pending += first
        try:
            if self._sparse_pending:
                os.lseek(self.fd, self._sparse_pending, os.SEEK_CUR)
                self._sparse_pending = 0
            mv = memoryview(chunk[first:])
            while mv:
                n = os.write(self.fd, mv)
                mv = mv[n:]
            return True
        except OSError as exc:
            self.write_error = exc
            return False
    def close(self):
        """Returns True on success, False on write/flush error."""
        ok = self.write_error is None
        if self.kind == "file" and self.fd is not None:
            if self.sparse:
                if self._sparse_buf:
                    tail = bytes(self._sparse_buf)
                    self._sparse_buf = bytearray()
                    if ok:
                        ok = self._write_sparse_segment(tail)
                if self._sparse_pending:
                    # ensure final size: seek to last byte and write a zero
                    try:
                        os.lseek(self.fd, self._sparse_pending - 1, os.SEEK_CUR)
                        os.write(self.fd, b"\0")
                    except OSError as exc:
                        self.write_error = exc
                        ok = False
                    self._sparse_pending = 0
            try:
                os.close(self.fd)
            except OSError as exc:
                if ok:
                    self.write_error = exc
                ok = False
            self.fd = None
        return ok and self.write_error is None

