    "tbz2", "tlz4", "woff2",
}

def is_excluded_compressed(filename):
    idx = filename.rfind(".")
    if idx <= 0:
        return False
    return filename[idx + 1:] in EXCLUDED_SUFFIXES

def expand_filenames(names):
    """Read --filelist content and -r expansion. Returns (list, had_input_names)."""
    inputs = list(names)
    # --filelist entries come after direct arguments
    for listname in ST.filelists:
        try:
            with open(listname, "rb") as fh:
                content = fh.read()
            if len(content) == 0:
                raise OSError("empty")
        except OSError:
            disp(1, f"zstd: error reading {listname} \n")
            raise ExitMain(1)
        parts = content.split(b"\n")
        if content.endswith(b"\n"):
            parts = parts[:-1]
        for part in parts:
            inputs.append(InputName(os.fsdecode(part), False))
    if not ST.recursive:
        return inputs, len(inputs) > 0
    expanded = []
    for item in inputs:
        if item.is_stdin:
            expanded.append(item)
            continue
        if _is_dir_for_expansion(item.text):
            _expand_dir(item.text, expanded)
        else:
            expanded.append(item)
    return expanded, len(inputs) > 0

def _is_dir_for_expansion(path):
    try:
        lst = os.lstat(path)
    except OSError:
        return False
    if stat_mod.S_ISLNK(lst.st_mode):
        if not ST.force:
            return False
        try:
            st = os.stat(path)
        except OSError:
            return False
        return stat_mod.S_ISDIR(st.st_mode)
    return stat_mod.S_ISDIR(lst.st_mode)

def _expand_dir(dirpath, out):
    try:
        with os.scandir(dirpath) as it:
            entries = list(it)
    except OSError as exc:
        disp(1, f"Cannot open directory '{dirpath}': {exc.strerror or str(exc)}\n")
        return
    for entry in entries:
        name = entry.name
        if name in (".", ".."):
            continue
        path = dirpath + "/" + name
        try:
            lst = os.lstat(path)
        except OSError:
            out.append(InputName(path, False))
            continue
        if stat_mod.S_ISLNK(lst.st_mode):
            if not ST.force:
                disp(2, f"Warning : {path} is a symbolic link, ignoring\n")
                continue
            # follow link
            try:
                st = os.stat(path)
                if stat_mod.S_ISDIR(st.st_mode):
                    _expand_dir(path, out)
                else:
                    out.append(InputName(path, False))
            except OSError:
                out.append(InputName(path, False))
            continue
        if stat_mod.S_ISDIR(lst.st_mode):
            _expand_dir(path, out)
        else:
            out.append(InputName(path, False))

def has_stdin_input(inputs):
    return any(x.is_stdin for x in inputs)

class SrcInfo:
    __slots__ = ("name", "is_stdin", "size", "stat", "fh", "fd")
    def __init__(self, name):
        self.name = name
        self.is_stdin = name.is_stdin
        self.size = None
        self.stat = None
        self.fh = None
        self.fd = None
    @property
    def display(self):
        return STDIN_MARK if self.is_stdin else self.name.text

def check_and_open_src(item):
    """Returns SrcInfo or None (error already reported)."""
    info = SrcInfo(item)
    if item.is_stdin:
        return info
    path = item.text
    # symlink check first (with FIFO-target bypass observed in the reference)
    try:
        lst = os.lstat(path)
        is_link = stat_mod.S_ISLNK(lst.st_mode)
    except OSError:
        is_link = False
        lst = None
    if is_link and not ST.force:
        # bypass if link target is a FIFO (e.g. /dev/stdin pointing at a pipe)
        bypass = False
        try:
            tgt = os.stat(path)
            if stat_mod.S_ISFIFO(tgt.st_mode):
                bypass = True
        except OSError:
            pass
        if not bypass:
            disp(2, f"Warning : {path} is a symbolic link, ignoring \n")
            return None
    try:
        st = os.stat(path)
    except OSError as exc:
        disp(1, f"zstd: can't stat {path} : {exc.strerror or str(exc)} -- ignored \n")
        return None
    if stat_mod.S_ISDIR(st.st_mode):
        disp(1, f"zstd: {path} is a directory -- ignored \n")
        return None
    if not (stat_mod.S_ISREG(st.st_mode) or stat_mod.S_ISFIFO(st.st_mode)):
        disp(1, f"zstd: {path} is not a regular file -- ignored \n")
        return None
    info.stat = st
    info.size = st.st_size if stat_mod.S_ISREG(st.st_mode) else None
    # open now (before any destination handling)
    try:
        fd = os.open(path, os.O_RDONLY)
    except OSError as exc:
        disp(1, f"zstd: {path}: {exc.strerror or str(exc)} \n")
        return None
    info.fd = fd
    info.fh = os.fdopen(os.dup(fd), "rb", buffering=0)
    os.close(fd)
    info.fd = info.fh.fileno()
    return info

def close_src(info):
    if info is not None and info.fh is not None:
        try:
            info.fh.close()
        except Exception:
            pass
        info.fh = None

class DstWriter:
    """Output sink: stdout, a regular file, or /dev/null-like test sink."""
    def __init__(self, kind, fd=None, path=None, sparse=False):
        self.kind = kind    # 'stdout' | 'file' | 'sink'
        self.fd = fd
        self.path = path
        self.sparse = sparse
        self.total = 0
        self._sparse_pending = 0
        self._sparse_buf = bytearray()
        self._sparse_pos_in_segment = 0
        self.write_error = None
    def write(self, data):
        if not data:
            return True
        self.total += len(data)
        if self.kind == "sink":
            return True
        if self.kind == "stdout":
            try:
                mv = memoryview(bytes(data))
                while mv:
                    n = os.write(1, mv)
                    mv = mv[n:]
                return True
            except OSError as exc:
                self.write_error = exc
                return False
        # file
        if self.sparse:
            return self._write_sparse_feed(data)
        try:
            mv = memoryview(bytes(data))
            while mv:
                n = os.write(self.fd, mv)
                mv = mv[n:]
            return True
        except OSError as exc:
            self.write_error = exc
            return False
    # sparse handling: process in 32 KiB segments
    def _write_sparse_feed(self, data):
        self._sparse_buf += bytes(data)
        while len(self._sparse_buf) >= 32768:
            chunk = bytes(self._sparse_buf[:32768])
            del self._sparse_buf[:32768]
            if not self._write_sparse_segment(chunk):
                return False
        return True
    def _write_sparse_segment(self, chunk):
        if not any(chunk):
            self._sparse_pending += len(chunk)
            return True
        # find first nonzero
        first = 0
        nb = len(chunk)
        while first < nb and chunk[first] == 0:
            first += 1
        self._sparse_pending += first
        try:
            if self._sparse_pending:
                os.lseek(self.fd, self._sparse_pending, os.SEEK_CUR)
                self._sparse_pending = 0
            mv = memoryview(chunk[first:])
            while mv:
                n = os.write(self.fd, mv)
                mv = mv[n:]
            return True
        except OSError as exc:
            self.write_error = exc
            return False
    def close(self):
        """Returns True on success, False on write/flush error."""
        ok = self.write_error is None
        if self.kind == "file" and self.fd is not None:
            if self.sparse:
                if self._sparse_buf:
                    tail = bytes(self._sparse_buf)
                    self._sparse_buf = bytearray()
                    if ok:
                        ok = self._write_sparse_segment(tail)
                if self._sparse_pending:
                    # ensure final size: seek to last byte and write a zero
                    try:
                        os.lseek(self.fd, self._sparse_pending - 1, os.SEEK_CUR)
                        os.write(self.fd, b"\0")
                    except OSError as exc:
                        self.write_error = exc
                        ok = False
                    self._sparse_pending = 0
            try:
                os.close(self.fd)
            except OSError as exc:
                if ok:
                    self.write_error = exc
                ok = False
            self.fd = None
        return ok and self.write_error is None

def _same_file(src_info, dst_path):
    if src_info is None or src_info.is_stdin or src_info.stat is None:
        return False
    try:
        dst_st = os.stat(dst_path)
    except OSError:
        return False
    return (dst_st.st_dev == src_info.stat.st_dev and dst_st.st_ino == src_info.stat.st_ino)

def _dst_is_regular(dst_path):
    try:
        st = os.stat(dst_path)
        return stat_mod.S_ISREG(st.st_mode)
    except OSError:
        return False

# result codes for open_dst_file
DST_OK = 0; DST_SKIPPED = 1; DST_ERROR = 2

def open_dst_file(src_info, dst_path, stdin_is_input, check_same=True, sparse=False):
    """Open a destination file. Returns (writer_or_None, status)."""
    if check_same and _same_file(src_info, dst_path):
        disp(1, "zstd: Refusing to open an output file which will overwrite the input file \n")
        return None, DST_ERROR
    if _dst_is_regular(dst_path) and not ST.force:
        if ST.display_level <= 1:
            disp(1, f"zstd: {dst_path} already exists; not overwritten  \n")
            return None, DST_SKIPPED
        if stdin_is_input:
            # printed unconditionally at this display level (level>=2 by construction)
            ewrite(f"zstd: {dst_path} already exists; stdin is an input - not proceeding.\n")
            return None, DST_SKIPPED
        ewrite(f"zstd: {dst_path} already exists; overwrite (y/n) ? ")
        ans = STDIN.read_line_first_char()
        if ans not in (b"y", b"Y"):
            ewrite("Not overwritten  \n \n")
            return None, DST_SKIPPED
    try:
        fd = os.open(dst_path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
    except OSError as exc:
        disp(1, f"zstd: {dst_path}: {exc.strerror or str(exc)}\n")
        return None, DST_ERROR
    # sparse only useful on regular files
    use_sparse = sparse
    if use_sparse:
        try:
            if not stat_mod.S_ISREG(os.fstat(fd).st_mode):
                use_sparse = False
        except OSError:
            use_sparse = False
    return DstWriter("file", fd=fd, path=dst_path, sparse=use_sparse), DST_OK

def copy_file_props(src_info, dst_path):
    """Copy permissions and timestamps from source to a regular dest file."""
    if src_info is None or src_info.is_stdin or dst_path is None:
        return
    try:
        st = os.stat(src_info.name.text)
    except OSError:
        return
    try:
        if os.path.exists(dst_path):
            os.chmod(dst_path, stat_mod.S_IMODE(st.st_mode))
            os.utime(dst_path, ns=(st.st_atime_ns, st.st_mtime_ns))
    except OSError:
        pass

def remove_dst_on_error(writer):
    """After a failed (de)compression to a file: remove it if regular."""
    if writer is None or writer.kind != "file" or not writer.path:
        return
    try:
        st = os.lstat(writer.path)
    except OSError:
        return
    if stat_mod.S_ISREG(st.st_mode):
        try:
            os.remove(writer.path)
        except OSError:
            pass
    else:
        disp(1, f"zstd: Refusing to remove non-regular file {writer.path}\n")

def derive_compress_output(src_path):
    return src_path + ST.out_suffix

_SUFFIXES_DEC = [(".tzst", ".tar"), (".tgz", ".tar"), (".zstd", ""), (".zst", ""), (".gz", "")]
def derive_decompress_output(src_path):
    """Returns derived output name or None if suffix unknown."""
    for suf, repl in _SUFFIXES_DEC:
        if src_path.endswith(suf) and len(src_path) > len(suf):
            return src_path[:len(src_path) - len(suf)] + repl
    return None

def apply_output_dir(dst_derived, src_path_for_flat):
    """Map a per-file derived output through --output-dir-{flat,mirror}."""
    if ST.output_dir_mirror is not None:
        # mirror: output dir + '/' + derived path (strip leading '/' of derived? reference keeps
        # out/tmp/... for absolute input; derived has no leading slash handling needed here)
        d = dst_derived
        if d.startswith("/"):
            d = d[1:]
        return ST.output_dir_mirror.rstrip("/") + "/" + d if ST.output_dir_mirror != "/" else "/" + d
    if ST.output_dir_flat is not None:
        base = dst_derived.rsplit("/", 1)[-1]
        outdir = ST.output_dir_flat
        return (outdir + base) if outdir.endswith("/") else (outdir + "/" + base)
    return dst_derived

def ensure_mirror_dirs(dst_path):
    if ST.output_dir_mirror is None:
        return
    parent = os.path.dirname(dst_path)
    if parent:
        try:
            os.makedirs(parent, exist_ok=True)
        except OSError:
            pass

