        raise TopLevelError(31, f"Stat failed on dictionary file {path}: {exc.strerror or str(exc)}")
    if not stat_mod.S_ISREG(st.st_mode):
        raise TopLevelError(32, f"Dictionary {path} must be a regular file.")
