    return 0  # system libzstd here has no MT support; output is single-thread form

class CompressStats:
    __slots__ = ("read_total", "written_total", "first_chunk_len", "first_consumed", "first_written")
    def __init__(self):
        self.read_total = 0
        self.written_total = 0
        self.first_chunk_len = 0
        self.first_consumed = 0
        self.first_written = 0

def compress_zstd(info, writer, dict_data, patch_data):
    lib = _load_lib()
    stats = CompressStats()
    ctx = lib.ZSTD_createCCtx()
    if not ctx:
        raise TopLevelError(11, "Allocation error : not enough memory")
    start_written = writer.total
    try:
        _set_param(ctx, CP_LEVEL, ST.clevel)
        _set_param(ctx, CP_CHECKSUM, 1 if ST.checksum_flag != 0 else 0)
        _set_param(ctx, CP_CONTENTSIZE, 1 if ST.content_size else 0)
        _set_param(ctx, CP_DICTID, 1 if ST.dict_id else 0)
        _apply_explicit_cparams(ctx)
        if ST.ldm_enabled:
            _set_param(ctx, CP_LDM_ENABLE, 1)
        if ST.target_cblock_size:
            _set_param(ctx, CP_EXP_TARGETCBLOCK, ST.target_cblock_size)
        if ST.compress_literals is not None:
            try:
                _set_param(ctx, CP_EXP_LITERALCOMP, 1 if ST.compress_literals else 0)
            except TopLevelError:
                pass
        if ST.size_hint:
            try:
                _set_param(ctx, CP_EXP_SRCSIZEHINT, min(ST.size_hint, 2147483647))
            except TopLevelError:
                pass
