        dict_buf = None; patch_buf = None
        if dict_data:
            dict_buf = ctypes.create_string_buffer(dict_data, len(dict_data))
            r = lib.ZSTD_CCtx_loadDictionary(ctx, ctypes.cast(dict_buf, ctypes.c_void_p), len(dict_data))
            if lib.ZSTD_isError(r):
                raise TopLevelError(11, lib_error_message(r))
        if patch_data:
            patch_buf = ctypes.create_string_buffer(patch_data, len(patch_data))
            r = lib.ZSTD_CCtx_refPrefix(ctx, ctypes.cast(patch_buf, ctypes.c_void_p), len(patch_data))
            if lib.ZSTD_isError(r):
                raise TopLevelError(11, lib_error_message(r))
        # pledged size
        pledged = None
        if info.is_stdin:
            if ST.stream_size:
                pledged = ST.stream_size
        elif info.size is not None:
            pledged = info.size
        elif ST.stream_size:
            pledged = ST.stream_size
        if pledged is not None:
            r = lib.ZSTD_CCtx_setPledgedSrcSize(ctx, int(pledged))
            if lib.ZSTD_isError(r):
                raise TopLevelError(11, lib_error_message(r))
        in_size = lib.ZSTD_CStreamInSize()
        out_size = lib.ZSTD_CStreamOutSize()
        out_buf = ctypes.create_string_buffer(out_size)
        first = True
        while True:
            chunk = src_read(info, in_size)
            stats.read_total += len(chunk)
            # Buffered reads return short only at EOF
            is_last = len(chunk) < in_size
            in_buf_mem = ctypes.create_string_buffer(chunk, len(chunk)) if chunk else ctypes.create_string_buffer(1)
            ib = _InBuf(ctypes.cast(in_buf_mem, ctypes.c_void_p), len(chunk), 0)
            end_op = 2 if is_last else 0
            while True:
                ob = _OutBuf(ctypes.cast(out_buf, ctypes.c_void_p), out_size, 0)
                r = lib.ZSTD_compressStream2(ctx, ctypes.byref(ob), ctypes.byref(ib), end_op)
                if lib.ZSTD_isError(r):
                    raise TopLevelError(11, lib_error_message(r))
                if ob.pos:
                    if not writer.write(out_buf.raw[:ob.pos]):
                        # write error: stop; caller reports on close
                        stats.written_total = writer.total - start_written
                        return stats
                if first:
                    stats.first_chunk_len = len(chunk)
                    stats.first_consumed = ib.pos
                    stats.first_written = writer.total - start_written
                    first = False
                if end_op == 2:
                    if r == 0:
                        break
                else:
                    if ib.pos >= ib.size:
                        break
            if is_last:
                break
