        return stats
    finally:
        lib.ZSTD_freeCCtx(ctx)

def compress_gzip(info, writer, dict_data, patch_data):
    stats = CompressStats()
    level = ST.clevel
    # zlib accepts -1..9; the reference passes the level through (clamped to 9
    # by its own logic for >9 by capping before the call in later versions,
    # but observed: >9 behaves as 9, <-1 is a hard deflateInit2 error)
    if level < -1:
        # deflateInit2 error -2  -> error 71
        msg = f"zstd: {info.display}: deflateInit2 error -2 \n"
        raise TopLevelError(71, msg)
    zlvl = 9 if level > 9 else level
    comp = zlib.compressobj(zlvl, zlib.DEFLATED, 31)
    start_written = writer.total
    first = True
    # zlib's gzip header is emitted with first compress/flush call
    while True:
        chunk = src_read(info, 131072)
        stats.read_total += len(chunk)
        if first:
            stats.first_chunk_len = len(chunk)
            stats.first_consumed = len(chunk)
            first = False
        if chunk:
            out = comp.compress(chunk)
            if out:
                if stats.first_written == 0:
                    stats.first_written = 10
                if not writer.write(out):
                    stats.written_total = writer.total - start_written
                    return stats
        if len(chunk) < 131072:
            break
    out = comp.flush()
    if out:
        writer.write(out)
    if stats.read_total == 0 and stats.first_written == 0:
        stats.first_written = 10
    stats.written_total = writer.total - start_written
    return stats

def compress_one(info, writer, dict_data, patch_data):
    if ST.format == "zstd":
        return compress_zstd(info, writer, dict_data, patch_data)
    if ST.format == "gzip":
        return compress_gzip(info, writer, dict_data, patch_data)
    if ST.format in ("xz", "lzma"):
        raise TopLevelError(20, f"zstd: {info.display}: file cannot be compressed as xz/lzma (zstd compiled without ZSTD_LZMACOMPRESS) -- ignored \n")
    if ST.format == "lz4":
        raise TopLevelError(20, f"zstd: {info.display}: file cannot be compressed as lz4 (zstd compiled without ZSTD_LZ4COMPRESS) -- ignored \n")
    raise AssertionError(ST.format)

