# ------------------------------------------------------------ decompression --
class BufferedReader:
    def __init__(self, info):
        self.info = info
        self.buf = bytearray()
        self.eof = False
    def _fill(self):
        if self.eof:
            return False
        data = src_read(self.info, 131072)
        if not data:
            self.eof = True
            return False
        self.buf += data
        return True
    def fill_up_to(self, n):
        while len(self.buf) < n and not self.eof:
            if not self._fill():
                break
    def peek(self, n):
        self.fill_up_to(n)
        return bytes(self.buf[:n])
    def take(self, n):
        self.fill_up_to(1)
        out = bytes(self.buf[:n])
        del self.buf[:n]
        return out
    def pushback(self, data):
        if data:
            self.buf = bytearray(data) + self.buf
    def read_rest(self):
        parts = [bytes(self.buf)]
        self.buf = bytearray()
        while not self.eof:
            data = src_read(self.info, 131072)
            if not data:
                self.eof = True
                break
            parts.append(data)
        return b"".join(parts)

def _make_dctx(dict_data, patch_data):
    lib = _load_lib()
    ctx = lib.ZSTD_createDCtx()
    if not ctx:
        raise TopLevelError(11, "Allocation error : not enough memory")
    mem = ST.effective_mem_limit()
    r = lib.ZSTD_DCtx_setMaxWindowSize(ctx, int(mem))
    if lib.ZSTD_isError(r):
        lib.ZSTD_freeDCtx(ctx)
        raise TopLevelError(11, lib_error_message(r))
    if ST.checksum_flag == 0:
        # experimental dParam 1002 disables checksum validation in this lib
        try:
            lib.ZSTD_DCtx_setParameter(ctx, 1002, 1)
        except Exception:
            pass
    keep = []
    if dict_data:
        buf = ctypes.create_string_buffer(dict_data, len(dict_data)); keep.append(buf)
        r = lib.ZSTD_DCtx_loadDictionary(ctx, ctypes.cast(buf, ctypes.c_void_p), len(dict_data))
        if lib.ZSTD_isError(r):
            lib.ZSTD_freeDCtx(ctx)
            raise TopLevelError(11, lib_error_message(r))
    if patch_data:
        buf = ctypes.create_string_buffer(patch_data, len(patch_data)); keep.append(buf)
        r = lib.ZSTD_DCtx_refPrefix(ctx, ctypes.cast(buf, ctypes.c_void_p), len(patch_data))
        if lib.ZSTD_isError(r):
            lib.ZSTD_freeDCtx(ctx)
            raise TopLevelError(11, lib_error_message(r))
    return ctx, keep

def validate_decompression_params():
    ctx, _keep = _make_dctx(None, None)
    _load_lib().ZSTD_freeDCtx(ctx)

def _frame_window_size(header_bytes):
    if len(header_bytes) < 5:
        return None
    lib = _load_lib()
    fh = _FrameHeader()
    buf = ctypes.create_string_buffer(header_bytes, len(header_bytes))
    r = lib.ZSTD_getFrameHeader(ctypes.byref(fh), ctypes.cast(buf, ctypes.c_void_p), len(header_bytes))
    if lib.ZSTD_isError(r) or r != 0:
        return None
    return int(fh.windowSize)

def _decode_error(src_display, message, window_size=None):
    text = f"{src_display} : Decoding error (36) : {message} \n"
    if message == "Frame requires too much memory for decoding" and window_size:
        maxw = ST.effective_mem_limit()
        # ceil log2
        wlog = max(0, (window_size - 1).bit_length())
        mb = (window_size + 1048575) // 1048576
        text += f"{src_display} : Window size larger than maximum : {window_size} > {maxw} \n"
        text += f"{src_display} : Use --long={wlog} or --memory={mb}MB \n"
    return PerFileError(text)

class DecompResult:
    __slots__ = ("bytes_out", "passthrough", "write_error")
    def __init__(self):
        self.bytes_out = 0
        self.passthrough = False
        self.write_error = False

def decompress_one(info, writer, dict_data, patch_data, progress_enabled=False):
    lib = _load_lib()
    src_display = info.display
    reader = BufferedReader(info)
    result = DecompResult()
    passthrough_allowed = False
    if ST.pass_through_setting is True:
        passthrough_allowed = True
    elif ST.pass_through_setting is None and ST.force and writer.kind == "stdout":
        passthrough_allowed = True
    ctx = None; keep = []
    first_frame = True
    progress_started = False
    start_total = writer.total
    def start_progress():
        nonlocal progress_started
        if progress_enabled and not progress_started:
            name = src_display
            # field of exactly 20 chars: truncate from the left if longer
            disp_bytes = fsb(name)
            if len(disp_bytes) > 20:
                disp_bytes = disp_bytes[-20:]
            field = disp_bytes + b" " * max(0, 20 - len(disp_bytes))
            ewrite(b"\r" + field + b" : 0 B...     ")
            progress_started = True
    try:
        while True:
            header = reader.peek(4)
            if len(header) == 0:
                if first_frame:
                    raise PerFileError(f"zstd: {src_display}: unexpected end of file \n")
                break
            if len(header) < 4:
                if first_frame and passthrough_allowed:
                    data = reader.read_rest()
                    if data:
                        writer.write(data)
                    result.passthrough = True
                    break
                raise PerFileError(f"zstd: {src_display}: unknown header \n")
            magic = int.from_bytes(header, "little")
            is_zstd = magic == 0xFD2FB528 or (0x184D2A50 <= magic <= 0x184D2A5F)
            is_gzip = header[0] == 0x1F and header[1] == 0x8B
            is_xz = (header[0] == 0xFD and header[1] == 0x37) or (header[0] == 0x5D and header[1] == 0x00)
            is_lz4 = magic == 0x184D2204
            if is_xz:
                raise PerFileError(f"zstd: {src_display}: xz/lzma file cannot be uncompressed (zstd compiled without HAVE_LZMA) -- ignored \n")
            if is_lz4:
                raise PerFileError(f"zstd: {src_display}: lz4 file cannot be uncompressed (zstd compiled without HAVE_LZ4) -- ignored \n")
            if not is_zstd and not is_gzip:
                if first_frame and passthrough_allowed:
                    data = reader.read_rest()
                    if data:
                        writer.write(data)
                    result.passthrough = True
                    break
                raise PerFileError(f"zstd: {src_display}: unsupported format \n")
            start_progress()
            if is_gzip:
                _decompress_gzip_member(reader, writer, src_display, result)
                if writer.write_error is not None:
                    result.write_error = True
                    result.bytes_out = writer.total - start_total
                    return result
            else:
                if ctx is None:
                    ctx, keep = _make_dctx(dict_data, patch_data)
                # capture window size for error hints
                hdr_bytes = reader.peek(18)
                wsize = _frame_window_size(hdr_bytes)
                _decompress_zstd_frame(ctx, reader, writer, src_display, wsize, result)
                if writer.write_error is not None:
                    result.write_error = True
                    result.bytes_out = writer.total - start_total
                    return result
                # reset session for a possible next frame
                try:
                    lib.ZSTD_DCtx_reset(ctx, 1)
                except Exception:
                    pass
            first_frame = False
        result.bytes_out = 0 if result.passthrough else (writer.total - start_total)
        result.write_error = writer.write_error is not None
        return result
    finally:
        if ctx is not None:
            lib.ZSTD_freeDCtx(ctx)

def _decompress_zstd_frame(ctx, reader, writer, src_display, window_size, result):
    lib = _load_lib()
    out_size = lib.ZSTD_DStreamOutSize()
    out_buf = ctypes.create_string_buffer(out_size)
    while True:
        chunk = reader.take(131072)
        if not chunk:
            raise PerFileError(f"{src_display} : Read error (39) : premature end \n")
        in_mem = ctypes.create_string_buffer(chunk, len(chunk))
        ib = _InBuf(ctypes.cast(in_mem, ctypes.c_void_p), len(chunk), 0)
        while ib.pos < ib.size:
            ob = _OutBuf(ctypes.cast(out_buf, ctypes.c_void_p), out_size, 0)
            r = lib.ZSTD_decompressStream(ctx, ctypes.byref(ob), ctypes.byref(ib))
            if lib.ZSTD_isError(r):
                raise _decode_error(src_display, lib_error_message(r), window_size)
            if ob.pos:
                if not writer.write(out_buf.raw[:ob.pos]):
                    return
            if r == 0:
                reader.pushback(chunk[ib.pos:])
                return

def _decompress_gzip_member(reader, writer, src_display, result):
    decomp = zlib.decompressobj(31)
    while True:
        chunk = reader.take(131072)
        if not chunk:
            raise PerFileError(f"zstd: {src_display}: premature gz end \n")
        try:
            out = decomp.decompress(chunk)
        except zlib.error:
            raise PerFileError(f"zstd: {src_display}: inflate error -3 \n")
        if out:
            if not writer.write(out):
                return
        if decomp.eof:
            reader.pushback(decomp.unused_data)
            return

