class BufferedReader:
    def __init__(self, info):
        self.info = info
        self.buf = bytearray()
        self.eof = False
    def _fill(self):
        if self.eof:
            return False
        data = src_read(self.info, 131072)
        if not data:
            self.eof = True
            return False
        self.buf += data
        return True
    def fill_up_to(self, n):
        while len(self.buf) < n and not self.eof:
            if not self._fill():
                break
    def peek(self, n):
        self.fill_up_to(n)
        return bytes(self.buf[:n])
    def take(self, n):
        self.fill_up_to(1)
        out = bytes(self.buf[:n])
        del self.buf[:n]
        return out
    def pushback(self, data):
        if data:
            self.buf = bytearray(data) + self.buf
    def read_rest(self):
        parts = [bytes(self.buf)]
        self.buf = bytearray()
        while not self.eof:
            data = src_read(self.info, 131072)
            if not data:
