    if ST.single_thread:
        return 0
    return ST.nb_threads & UINT_MAX

def _compress_threads_display():
    if ST.single_thread:
        return 0
    raw = ST.nb_threads
    if raw == 0:
        return core_count(ST.auto_threads_logical)
    if raw == -1:
        return 4
    return raw & UINT_MAX

def _bench_threads_display():
    if ST.single_thread:
        return 0
    raw = ST.nb_threads
    if raw == 0:
        return core_count(ST.auto_threads_logical)
    if raw == -1:
        return 1
    return raw & UINT_MAX

