# -------------------------------------------------------- file operations --
def _padded_name(name, width=20):
    b = fsb(name)
    if len(b) < width:
        b = b + b" " * (width - len(b))
    return b

def compress_summary_line(src_display, src_size, dst_size, dst_display):
    name = _padded_name(src_display)
    hs = human_size(src_size, padded_number_width=6)
    hd = human_size(dst_size, padded_number_width=6)
    if src_size == 0:
        return name + f" :  ({hs} => {hd}, ".encode() + fsb(dst_display) + b") \n"
    pct = dst_size * 100.0 / src_size if src_size else 0.0
    return name + f" :{pct:6.2f}%   ({hs} => {hd}, ".encode() + fsb(dst_display) + b") \n"

def decompress_summary_line(src_display, nbytes):
    return _padded_name(src_display) + f": {nbytes} bytes \n".encode()

def completed_line(src_display, wall, cpu):
    load = int(cpu / wall * 100) if wall > 0 else 100
    return _padded_name(src_display) + f" : Completed in {wall:.2f} sec  (cpu load : {load}%)\n".encode()

def _format_line():
    parts = [f"--format={ST.out_suffix} --no-sparse"]
    if not ST.dict_id:
        parts.append("--no-dictID")
    if ST.checksum_flag == 2:
        parts.append("--check")
    elif ST.checksum_flag == 0:
        parts.append("--no-check")
    parts.append(f"--jobsize={ST.block_size}")
    if ST.adapt:
        parts.append(f"--adapt=min={ST.adapt_min},max={ST.adapt_max}")
    if ST.row_match_finder is not None:
        parts.append("--no-row-match-finder" if ST.row_match_finder else "--row-match-finder")
    if ST.rsyncable:
        parts.append("--rsyncable")
    if ST.stream_size:
        parts.append(f"--stream-size={ST.stream_size}")
    if ST.size_hint:
        parts.append(f"--size-hint={ST.size_hint}")
    if ST.target_cblock_size:
        parts.append(f"--target-compressed-block-size={ST.target_cblock_size}")
    if ST.compress_literals is not None:
        parts.append("--compress-literals" if ST.compress_literals else "--no-compress-literals")
    parts.append(f"--memory={ST.effective_mem_limit()}")
    parts.append(f"--threads={_compress_threads_display()}")
    if ST.exclude_compressed:
        parts.append("--exclude-compressed")
    parts.append("--content-size" if ST.content_size else "--no-content-size")
    return " ".join(parts) + "\n"

def _compress_threads_raw_display():
    if ST.single_thread:
        return 0
    return ST.nb_threads & UINT_MAX

def _compress_threads_display():
    if ST.single_thread:
        return 0
    raw = ST.nb_threads
    if raw == 0:
        return core_count(ST.auto_threads_logical)
    if raw == -1:
        return 4
    return raw & UINT_MAX

def _bench_threads_display():
    if ST.single_thread:
        return 0
    raw = ST.nb_threads
    if raw == 0:
        return core_count(ST.auto_threads_logical)
    if raw == -1:
        return 1
    return raw & UINT_MAX

def _stat_size_for_params(item):
    if item.is_stdin:
        return None
    try:
        st = os.stat(item.text)
        if stat_mod.S_ISREG(st.st_mode):
            return st.st_size
    except OSError:
        pass
    return None

def _dict_size_for_params():
    path = ST.dict_file if ST.dict_file is not None else ST.patch_from
    if path is None:
        return 0
    try:
        return os.stat(path).st_size
    except OSError:
        return 0

def _show_cparams_block(src_display, params, src_size):
    if src_size is None:
        head = f"{src_display} (src size unknown)\n"
    else:
        head = f"{src_display} ({src_size} bytes)\n"
    lines = [head,
             f" - windowLog     : {params['windowLog']}\n",
             f" - chainLog      : {params['chainLog']}\n",
             f" - hashLog       : {params['hashLog']}\n",
             f" - searchLog     : {params['searchLog']}\n",
             f" - minMatch      : {params['minMatch']}\n",
             f" - targetLength  : {params['targetLength']}\n",
             f" - strategy      : {STRATEGY_NAMES.get(params['strategy'], 'ZSTD_fast')} ({params['strategy']})\n"]
    ewrite("".join(lines))

def _zstd_params_line(params_with_overrides):
    p = params_with_overrides
    return (f"--zstd=wlog={p['windowLog']},clog={p['chainLog']},hlog={p['hashLog']},"
            f"slog={p['searchLog']},mml={p['minMatch']},tlen={p['targetLength']},strat={p['strategy']}\n")

def _params_with_overrides(base):
    p = dict(base)
    for field in ("windowLog", "chainLog", "hashLog", "searchLog", "minMatch", "targetLength", "strategy"):
        if ST.cparams.get(field):
            p[field] = ST.cparams[field]
    return p

def _progress_enabled(single_stdout):
    lvl = fio_display_level(single_stdout)
    if ST.progress_setting is True:
        return lvl > 0
    if ST.progress_setting is False:
        return False
    return lvl >= 2 and _stderr_is_tty()

def _stderr_is_tty():
    try:
        return os.isatty(2)
    except Exception:
        return False

def _summary_visible(single_stdout, progress_enabled):
    lvl = fio_display_level(single_stdout)
    if lvl >= 2:
        return True
    if progress_enabled and lvl > 0:
        return True
    return False

CLEAR_LINE = b"\r" + b" " * 79 + b"\r"

def _emit_compress_progress(src_display, src_size_known, stats, dst_size):
    """One simulated progress update, emitted before the summary."""
    ewrite(CLEAR_LINE)
    if ST.format == "gzip":
        if stats.read_total == 0:
            # no Read line for empty gzip input, only the clear
            return
        read_mb = stats.first_chunk_len >> 20
        compressed_at = 10
        pct = (compressed_at * 100.0 / stats.first_chunk_len) if stats.first_chunk_len else 0.0
        if src_size_known is not None:
            total_mb = src_size_known >> 20
            ewrite(f"Read : {read_mb} / {total_mb} MB ==> {pct:.2f}% ")
        else:
            ewrite(f"Read : {read_mb} MB ==> {pct:.2f}% ")
        ewrite(CLEAR_LINE)
        return
    verbose = ST.display_level >= 3
    total_read = stats.read_total
    # decide the simulated state
    if src_size_known is not None and src_size_known <= 131072:
        read_at = total_read
        consumed = total_read
        compressed_at = dst_size - (4 if (ST.checksum_flag != 0 and total_read > 0) else 0)
        if compressed_at < 0:
            compressed_at = 0
        buffered = 0
    elif src_size_known is not None and src_size_known <= 524288:
        read_at = min(131072, total_read)
        consumed = read_at
        compressed_at = stats.first_written
        buffered = 0
    else:
        # large / unknown size: first update with buffered first chunk
        if ST.single_thread and src_size_known is not None:
            read_at = min(131072, total_read)
            consumed = read_at
            compressed_at = stats.first_written
            buffered = 0
        else:
            read_at = 0
            consumed = 0
            compressed_at = 0
            buffered = min(131072, total_read) if total_read else stats.first_chunk_len
    if verbose:
        pct = (compressed_at * 100.0 / consumed) if consumed else 0.0
        lvl = ST.clevel if ST.clevel else 3
        ewrite(f"(L{lvl}) Buffered: {human_size(buffered, padded_number_width=6)} - "
               f"Consumed: {human_size(consumed, padded_number_width=6)} - "
               f"Compressed: {human_size(compressed_at, padded_number_width=6)} => {pct:.2f}% ")
    else:
        pct = (compressed_at * 100.0 / read_at) if read_at else 0.0
        if src_size_known is not None:
            ewrite(f"Read: {human_size(read_at, padded_number_width=6, padded_suffix=True)} / "
                   f"{human_size(src_size_known, padded_number_width=6, padded_suffix=True)} ==> {pct:3.0f}%")
        else:
            ewrite(f"Read: {human_size(read_at, padded_number_width=6, padded_suffix=True)}  ==> {pct:3.0f}%")
    ewrite(CLEAR_LINE)

def _require_concatenation_confirmation(out_name, is_stdout, stdin_is_input, single_stdout):
    """Returns True to proceed."""
    fio = fio_display_level(single_stdout)
    if is_stdout:
        if fio >= 2:
            ewrite("zstd: WARNING: all input files will be processed and concatenated into stdout. \n")
            ewrite("The concatenated output CANNOT regenerate original file names nor directory structure. \n")
        return True
    lines = [f"zstd: WARNING: all input files will be processed and concatenated into a single output file: {out_name} \n",
             "The concatenated output CANNOT regenerate original file names nor directory structure. \n"]
    if ST.remove_src:
        lines.append("Since it's a destructive operation, input files will not be removed. \n")
    if not ST.force:
        if ST.display_level <= 1:
            disp(1, "Concatenating multiple processed inputs into a single output loses file metadata. \nAborting. \n")
            return False
        for line in lines:
            ewrite(line)
        if stdin_is_input:
            ewrite("stdin is an input - not proceeding.\n")
            return False
        ewrite("Proceed? (y/n): ")
        ans = STDIN.read_line_first_char()
        if ans not in (b"y", b"Y"):
            ewrite("Aborting... \n")
            return False
        return True
    else:
        if fio >= 2:
            for line in lines:
                ewrite(line)
        return True

def run_file_operation(inputs):
    operation = ST.operation
    is_compress = operation == "compress"
    is_test = operation == "test"
    # stdin implicit
    if not inputs:
        inputs = [InputName(STDIN_MARK, True)]
    stdin_is_input = has_stdin_input(inputs)
    nb = len(inputs)
    single_stdout = False
    if not is_test:
        if ST.output_file == STDOUT_MARK:
            single_stdout = True
        elif ST.output_file is None and nb == 1 and inputs[0].is_stdin:
            single_stdout = True
    fio = fio_display_level(single_stdout)
    progress_enabled = (operation in ("compress", "decompress", "test")) and _progress_enabled(single_stdout)
    summary_visible = _summary_visible(single_stdout, progress_enabled)

    if is_compress and ST.display_level >= 4:
        ewrite(f"Compressing with {_compress_threads_raw_display()} worker threads \n")
    if is_compress:
        clamp_clevel()
        # second NBTHREADS warning from file-io when threads unset
        if ST.nb_threads == -1 and not ST.single_thread:
            warn_env_nbthreads_if_invalid(fio >= 2)
    if not is_compress:
        clamp_clevel()

    # stats / params phase (compression only)
    dict_size_params = _dict_size_for_params()
    if is_compress and inputs:
        for item in inputs:
            sz = _stat_size_for_params(item)
            params = get_cparams(ST.clevel, sz, dict_size_params)
            if ST.show_default_cparams:
                _show_cparams_block(item.display, params, sz)
            if ST.display_level >= 4:
                ewrite(_zstd_params_line(_params_with_overrides(params)))
        if ST.display_level >= 4:
            ewrite(_format_line())

    # resources: dictionary loading + parameter validation
    dict_data = None; patch_data = None
    dict_path = ST.dict_file; patch_path = ST.patch_from
    # stage-stat first for patch stream-size check ordering
    if patch_path is not None and is_compress:
        # stat errors come before the stream-size requirement
        load_dict_file(patch_path, stage_stat_only=True)
        if stdin_is_input and not ST.stream_size:
            raise TopLevelError(42, "Using --patch-from with stdin requires --stream-size")
    if dict_path is not None:
        dict_data = load_dict_file(dict_path)
    if patch_path is not None:
        patch_data = load_dict_file(patch_path)
    if is_compress:
        validate_compression_params()
        if ST.display_level >= 6:
            ewrite("FIO_createCResources \n")
        if ST.display_level >= 5:
            ewrite(f"set nb workers = {_compress_threads_display()} \n")
    else:
        validate_decompression_params()

    if ST.remove_src and _output_is_stdout_for(inputs, single_stdout) and not is_test:
        if ST.display_level >= 4:
            ewrite("Note: src files are not removed when output is stdout \n")

    # single-output handling
    single_output = (ST.output_file is not None) and not is_test
    shared_writer = None
    shared_dst_display = None
    if single_output and nb > 1:
        is_stdout_out = (ST.output_file == STDOUT_MARK)
        if not _require_concatenation_confirmation(ST.output_file, is_stdout_out, stdin_is_input, single_stdout):
            return 1
        if is_stdout_out:
            shared_writer = DstWriter("stdout")
            shared_dst_display = STDOUT_MARK
            if ST.display_level >= 4:
                ewrite("Using stdout for output \n")
                if not is_compress:
                    _sparse_stdout_note(writer_is_stdout=True)
        else:
            dst_path = ST.output_file
            ensure_mirror_dirs(dst_path) if ST.output_dir_mirror is not None else None
            sparse = _sparse_enabled_for(False)
            writer, status = open_dst_file(None, dst_path, stdin_is_input, check_same=False, sparse=sparse)
            if writer is None:
                return 1
            shared_writer = writer
            shared_dst_display = dst_path
    elif single_output and ST.output_file == STDOUT_MARK:
        if ST.display_level >= 4 and nb >= 1:
            # "Using stdout" notes are printed per file in the loop instead
            pass

    total_src = 0; total_dst = 0; nb_processed = 0; errors = 0
    stdin_used = False
    # for flat collision warnings
    flat_basenames = []
    for item in inputs:
        src_display = item.display
        if item.is_stdin:
            if stdin_used:
                # abort whole operation
                if shared_writer is not None and shared_writer.kind == "file":
                    shared_writer.close()
                raise TopLevelError(37, "Read error")
            stdin_used = True
        if is_compress and ST.exclude_compressed and not item.is_stdin and is_excluded_compressed(item.text):
            if ST.display_level >= 4:
                ewrite(f"File is already compressed : {item.text} \n")
            nb_processed += 1
            continue
        if ST.output_dir_flat is not None and ST.output_dir_mirror is None and not item.is_stdin:
            flat_basenames.append(item.text.rsplit("/", 1)[-1])
        # derived output name / suffix check (decompression, per-file outputs)
        derived_dst = None
        if not single_output and not is_test:
            if item.is_stdin:
                derived_dst = STDOUT_MARK
            elif is_compress:
                derived_dst = apply_output_dir(derive_compress_output(item.text), item.text)
            else:
                d = derive_decompress_output(item.text)
                if d is None:
                    disp(1, f"zstd: {item.text}: unknown suffix (.zst/.tzst/.gz/.tgz expected). Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n")
                    errors += 1
                    continue
                derived_dst = apply_output_dir(d, item.text)
        info = check_and_open_src(item)
        if info is None:
            errors += 1
            continue
        # determine writer
        writer = None; dst_display = None; dst_path_for_props = None
        own_writer = False
        if is_test:
            writer = DstWriter("sink")
            dst_display = STDOUT_MARK
        elif single_output:
            if nb > 1:
                writer = shared_writer
                dst_display = shared_dst_display
                dst_path_for_props = ST.output_file if ST.output_file != STDOUT_MARK else None
            elif ST.output_file == STDOUT_MARK:
                writer = DstWriter("stdout")
                dst_display = STDOUT_MARK
                own_writer = True
            else:
                dst_path = ST.output_file
                sparse = _sparse_enabled_for(False)
                if ST.display_level >= 6:
                    ewrite(f"FIO_compressFilename_srcFile: {src_display} \n")
                    ewrite(f"FIO_compressFilename_dstFile: opening dst: {dst_path} \n")
                w, status = open_dst_file(info, dst_path, stdin_is_input, check_same=True, sparse=sparse)
                if w is None:
                    close_src(info)
                    errors += 1
                    continue
                writer = w; own_writer = True
                dst_display = dst_path; dst_path_for_props = dst_path
        else:
            # per-file output
            if derived_dst == STDOUT_MARK:
                writer = DstWriter("stdout")
                dst_display = STDOUT_MARK
                own_writer = True
                if ST.display_level >= 6 and is_compress:
                    ewrite(f"FIO_compressFilename_srcFile: {src_display} \n")
                    ewrite(f"FIO_compressFilename_dstFile: opening dst: {dst_display} \n")
            else:
                if ST.display_level >= 6 and is_compress:
                    ewrite(f"FIO_compressFilename_srcFile: {src_display} \n")
                    ewrite(f"FIO_compressFilename_dstFile: opening dst: {derived_dst} \n")
                ensure_mirror_dirs(derived_dst)
                sparse = _sparse_enabled_for(False)
                w, status = open_dst_file(info, derived_dst, stdin_is_input, check_same=True, sparse=sparse)
                if w is None:
                    close_src(info)
                    errors += 1
                    continue
                writer = w; own_writer = True
                dst_display = derived_dst; dst_path_for_props = derived_dst
        # verbose Using / sparse notes (per file, stdout outputs)
        is_stdout_writer = writer.kind == "stdout"
        if ST.display_level >= 4 and not (single_output and nb > 1):
            if item.is_stdin:
                ewrite("Using stdin for input \n")
            if is_stdout_writer:
                ewrite("Using stdout for output \n")
                if not is_compress:
                    _sparse_stdout_note(writer_is_stdout=True)
        if is_stdout_writer and writer.kind == "file":
            pass
        # sparse flag for file writers opened above was set via _sparse_enabled_for
        wall0 = time.perf_counter(); cpu0 = time.process_time()
        result_ok = True; per_file_error = False
        src_read_bytes = 0; dst_written = 0; passthrough = False
        try:
            if is_compress:
                if ST.display_level >= 5:
                    sztxt = info.size if info.size is not None else 18446744073709551615
                    ewrite(f"{src_display}: {sztxt} bytes \n")
                if ST.display_level >= 6:
                    fmtname = {"zstd": "zstd", "gzip": "gzip", "xz": "xz", "lzma": "lzma", "lz4": "lz4"}[ST.format]
                    ewrite(f"compression using {fmtname} format \n")
                if ST.display_level >= 4 and ST.format == "zstd":
                    ewrite(f"Decompression will require {_decomp_requirement(info)} B of memory\n")
                cstats = compress_one(info, writer, dict_data, patch_data)
                src_read_bytes = cstats.read_total
                dst_written = cstats.written_total
                if ST.display_level >= 6 and ST.format == "zstd":
                    ewrite(f"fread {cstats.read_total} bytes from source \n")
                    ewrite(f"ZSTD_compress_generic(end:2) => input pos({cstats.read_total})<=({cstats.read_total})size ; output generated {cstats.written_total} bytes \n")
                if progress_enabled and nb == 1:
                    _emit_compress_progress(src_display, info.size, cstats, dst_written)
            else:
                # enable sparse on this file writer if appropriate
                if writer.kind == "file" and _sparse_enabled_for(True):
                    writer.sparse = True
                dres = decompress_one(info, writer, dict_data, patch_data,
                                      progress_enabled=progress_enabled and nb == 1)
                src_read_bytes = 0
                dst_written = dres.bytes_out
                passthrough = dres.passthrough
        except PerFileError as exc:
            # error text already formatted
            if ST.display_level >= 1 or fio >= 1:
                ewrite(str(exc))
            result_ok = False; per_file_error = True
        except TopLevelError:
            # close own/shared writer without removal of compressed outputs
            if own_writer and writer.kind == "file":
                writer.close()
            close_src(info)
            raise
        wall = time.perf_counter() - wall0; cpu = time.process_time() - cpu0
        writer_total_before = writer.total
        close_ok = True
        if own_writer and writer.kind == "file":
            close_ok = writer.close()
        # summaries / error handling
        if result_ok and not per_file_error:
            show_individual = summary_visible and (nb == 1 or ST.display_level >= 3)
            if is_compress:
                total_src += src_read_bytes; total_dst += dst_written
                if show_individual:
                    if progress_enabled and nb == 1:
                        pass  # progress already cleared the line
                    ewrite(compress_summary_line(src_display, src_read_bytes, dst_written, dst_display))
                    if ST.display_level >= 4:
                        ewrite(completed_line(src_display, wall, cpu))
                if ST.display_level >= 6 and is_compress and own_writer and writer.kind == "file":
                    ewrite(f"FIO_compressFilename_dstFile: closing dst: {dst_display} \n")
            else:
                if not passthrough:
                    total_dst += dst_written
                if show_individual and not passthrough:
                    if progress_enabled and nb == 1:
                        ewrite(CLEAR_LINE)
                    ewrite(decompress_summary_line(src_display, dst_written))
            if not close_ok:
                err = writer.write_error
                disp(1, f"zstd: {dst_display}: {err.strerror or str(err)} \n" if err else f"zstd: {dst_display}: Write error \n")
                remove_dst_on_error(writer)
                errors += 1
            else:
                nb_processed += 1
                if own_writer and writer.kind == "file" and dst_path_for_props:
                    copy_file_props(info, dst_path_for_props)
                elif shared_writer is not None and nb == 1 and dst_path_for_props:
                    copy_file_props(info, dst_path_for_props)
                if ST.remove_src and not item.is_stdin and writer.kind != "stdout" and not is_test:
                    try:
                        os.remove(item.text)
                    except OSError:
                        pass
        else:
            errors += 1
            if not is_compress:
                # decompression errors remove the output file
                if own_writer and writer.kind == "file":
                    writer.close()
                    remove_dst_on_error(writer)
            else:
                if own_writer and writer.kind == "file":
                    # close already done above; keep file (matches observed behaviour
                    # for most compression error paths)
                    pass
        close_src(info)

    if shared_writer is not None and shared_writer.kind == "file":
        shared_writer.close()
    # flat collision warnings
    if ST.output_dir_flat is not None and ST.output_dir_mirror is None and flat_basenames:
        _emit_flat_collision_warnings(flat_basenames, fio)
    # multiple-file summaries
    if nb > 1 and nb_processed > 0 and summary_visible:
        if is_compress:
            hs = human_size(total_src, padded_number_width=6, padded_suffix=True)
            hd = human_size(total_dst, padded_number_width=6, padded_suffix=True)
            if total_src == 0:
                ewrite(f"{nb_processed:3d} files compressed : ({hs} => {hd})\n")
            else:
                pct = total_dst * 100.0 / total_src
                ewrite(f"{nb_processed:3d} files compressed : {pct:.2f}% ({hs} => {hd})\n")
        else:
            ewrite(f"{nb_processed} files decompressed : {total_dst:7d} bytes total \n")
    return 1 if errors else 0

def _output_is_stdout_for(inputs, single_stdout):
    if single_stdout:
        return True
    if ST.output_file == STDOUT_MARK:
        return True
    return False

def _sparse_enabled_for(is_decompress_path):
    # sparse writing is a decompression-to-file feature
    return False

def _sparse_stdout_note(writer_is_stdout=False):
    if ST.sparse_setting == 2:
        ewrite("Sparse File Support is automatically disabled on stdout ; try --sparse \n")

def _decomp_requirement(info):
    # bytes of decompression memory required for this frame (display only)
    if info.size is not None:
        return info.size
    if ST.stream_size:
        return ST.stream_size
    wl = ST.cparams.get("windowLog", 0)
    if wl:
        return 1 << wl
    params = get_cparams(ST.clevel, None, 0)
    return 1 << params["windowLog"]

def _emit_flat_collision_warnings(basenames, fio_level):
    if fio_level < 2:
        return
    names = sorted(basenames)
    for a, b in zip(names, names[1:]):
        if a == b:
            ewrite(f"WARNING: Two files have same filename: {a}\n")

