    b = fsb(base)
    if len(b) > 18:
        b = b[-18:]
    return os.fsdecode(b)

def _bench_ratio_str(ratio):
    if ratio < 10:
        return f"{ratio:.3f}"
    if ratio < 100:
        return f"{ratio:.2f}"
    return f"{ratio:.1f}"

def _bench_speed_str(speed, quiet_comp=False):
    if quiet_comp:
        return f"{speed:6.2f}"
    if speed < 10:
        return f"{speed:6.2f}"
    return f"{speed:6.1f}"

def _bench_load_file(path, show_loading=True):
    try:
        st = os.stat(path)
        if not stat_mod.S_ISREG(st.st_mode):
            raise OSError("not regular")
    except OSError:
        raise BenchError(15, "Error loading files")
    if show_loading and ST.display_level >= 2:
        owrite(f"Loading {path}...       \r")
    try:
        with open(path, "rb") as fh:
            data = fh.read()
    except OSError:
        raise BenchError(15, "Error loading files")
    if len(data) != st.st_size:
        raise BenchError(15, "Error loading files")
    return data

def _bench_one_shot_compress(data, level, dict_data):
    lib = _load_lib()
    ctx = lib.ZSTD_createCCtx()
    if not ctx:
        raise BenchError(1, "Error : allocation failed \n")
    try:
        def setp(pid, v, expr):
            r = lib.ZSTD_CCtx_setParameter(ctx, pid, int(v))
            if lib.ZSTD_isError(r):
                raise BenchError(1, f"Error : ZSTD_CCtx_setParameter( ctx, {expr}, (int)comprParams->{expr.split('_')[-1]}) failed : {lib_error_message(r)} \n")
        r = lib.ZSTD_CCtx_setParameter(ctx, CP_LEVEL, int(level))
        if lib.ZSTD_isError(r):
            raise BenchError(1, f"Error : {lib_error_message(r)} \n")
        # explicit cparams (bench applies them per level)
        names = [("windowLog", CP_WINDOWLOG, "ZSTD_c_windowLog"), ("chainLog", CP_CHAINLOG, "ZSTD_c_chainLog"),
                 ("hashLog", CP_HASHLOG, "ZSTD_c_hashLog"), ("searchLog", CP_SEARCHLOG, "ZSTD_c_searchLog"),
                 ("minMatch", CP_MINMATCH, "ZSTD_c_minMatch"), ("targetLength", CP_TARGETLENGTH, "ZSTD_c_targetLength"),
                 ("strategy", CP_STRATEGY, "ZSTD_c_strategy")]
        for field, pid, expr in names:
            if ST.cparams.get(field):
                # message format for chainLog is known; others approximated
                setp(pid, ST.cparams[field], expr)
        if ST.ldm_enabled:
            try:
                _set_param(ctx, CP_LDM_ENABLE, 1)
            except TopLevelError as e:
                raise BenchError(1, f"Error : {e.message} \n")
        buf = None
        if dict_data:
            buf = ctypes.create_string_buffer(dict_data, len(dict_data))
            r = lib.ZSTD_CCtx_loadDictionary(ctx, ctypes.cast(buf, ctypes.c_void_p), len(dict_data))
            if lib.ZSTD_isError(r):
                raise BenchError(1, f"Error : {lib_error_message(r)} \n")
        r = lib.ZSTD_CCtx_setPledgedSrcSize(ctx, len(data))
        if lib.ZSTD_isError(r):
            raise BenchError(1, f"Error : {lib_error_message(r)} \n")
        bound = lib.ZSTD_compressBound(len(data))
        out = ctypes.create_string_buffer(bound)
        inbuf = ctypes.create_string_buffer(data, len(data)) if data else ctypes.create_string_buffer(1)
        n = lib.ZSTD_compress2(ctx, ctypes.cast(out, ctypes.c_void_p), bound,
                               ctypes.cast(inbuf, ctypes.c_void_p), len(data))
        if lib.ZSTD_isError(n):
            raise BenchError(1, f"Error : {lib_error_message(n)} \n")
        return out.raw[:n]
    finally:
        lib.ZSTD_freeCCtx(ctx)

def _bench_one_shot_decompress(data, out_size, dict_data):
    lib = _load_lib()
    ctx = lib.ZSTD_createDCtx()
    if not ctx:
        raise BenchError(1, "Error : allocation failed \n")
    try:
        buf = None
        if dict_data:
            buf = ctypes.create_string_buffer(dict_data, len(dict_data))
            r = lib.ZSTD_DCtx_loadDictionary(ctx, ctypes.cast(buf, ctypes.c_void_p), len(dict_data))
            if lib.ZSTD_isError(r):
                raise BenchError(1, f"Error : {lib_error_message(r)} \n")
        out = ctypes.create_string_buffer(max(1, out_size))
        inbuf = ctypes.create_string_buffer(data, len(data)) if data else ctypes.create_string_buffer(1)
        # use stream API via a tiny wrapper through decompressStream by feeding once
        ib = _InBuf(ctypes.cast(inbuf, ctypes.c_void_p), len(data), 0)
        ob = _OutBuf(ctypes.cast(out, ctypes.c_void_p), max(1, out_size), 0)
        # loop in case output buffer == size but multiple frames are in data
        total = 0
        out_all = bytearray()
        while ib.pos < ib.size:
            ob.pos = 0
            r = lib.ZSTD_decompressStream(ctx, ctypes.byref(ob), ctypes.byref(ib))
            if lib.ZSTD_isError(r):
                raise BenchError(1, f"Error : {lib_error_message(r)} \n")
            out_all += out.raw[:ob.pos]
            if r == 0:
                lib.ZSTD_DCtx_reset(ctx, 1)
        return bytes(out_all)
    finally:
        lib.ZSTD_freeDCtx(ctx)

def _bench_timed(fn, min_seconds):
    """Run fn repeatedly; return best ns per call."""
    best = None
    total = 0
    count = 1
    rounds = 0
    while True:
        start = time.perf_counter_ns()
        for _ in range(count):
            fn()
        elapsed = time.perf_counter_ns() - start
        if elapsed <= 0:
            elapsed = 1
        per = elapsed / count
        if best is None or per < best:
            best = per
        total += elapsed
        rounds += 1
        if min_seconds <= 0:
            break
        if total >= min_seconds * 1000000000:
            break
        # scale count toward the requested duration
        target = min_seconds * 1000000000
        if elapsed > 0:
            new_count = int(count * target / elapsed) + 1
        else:
            new_count = count * 10
        if new_count <= count:
            new_count = count + 1
        count = new_count
        if rounds > 10000:
            break
    return best

def _generate_synthetic():
    if ST.compressibility is None:
        # "Lorem ipsum" sample: pseudo-natural text, deterministic.
        words = ("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod "
                 "tempor incididunt ut labore et dolore magna aliqua enim ad minim veniam "
                 "quis nostrud exercitation ullamco laboris nisi aliquip ex ea commodo "
                 "consequat duis aute irure in reprehenderit voluptate velit esse cillum "
                 "fugiat nulla pariatur excepteur sint occaecat cupidatat non proident "
                 "sunt culpa qui officia deserunt mollit anim id est laborum").split()
        out = bytearray()
        seed = 0x9E3779B9
        def rnd():
            nonlocal seed
            seed ^= (seed << 13) & 0xFFFFFFFF
            seed ^= seed >> 17
            seed ^= (seed << 5) & 0xFFFFFFFF
            return seed & 0xFFFFFFFF
        while len(out) < 10000000:
            nwords = 4 + rnd() % 10
            sentence = []
            for i in range(nwords):
                w = words[rnd() % len(words)]
                sentence.append(w)
            s = " ".join(sentence).capitalize() + ". "
            out += s.encode()
        return bytes(out[:10000000]), "Lorem ipsum"
    pct = int(ST.compressibility)
    # deterministic compressible data
    out = bytearray()
    seed = 0x1234567
    def rndbyte():
        nonlocal seed
        seed = (seed * 1103515245 + 12345) & 0x7FFFFFFF
        return (seed >> 8) & 0xFF
    pattern = bytes(range(256))
    if pct >= 100:
        while len(out) < 10000000:
            out += pattern
        return bytes(out[:10000000]), f"Synthetic {pct}%"
    if pct <= 0:
        return bytes(rndbyte() for _ in range(10000000)), f"Synthetic {pct}%"
    # interleaved pattern / random in small runs
    pos = 0
    while len(out) < 10000000:
        run = 50 + rndbyte()
        if (rndbyte() % 100) < pct:
            seg = (pattern[pos % 256:] + pattern * 2)[:run]
            out += seg; pos += run
        else:
            out += bytes(rndbyte() for _ in range(run))
    return bytes(out[:10000000]), f"Synthetic {pct}%"

