        for data in flat:
            info = _analyze_bytes_for_bench(data)
            if info is None:
                # cannot determine vs invalid decided by caller through temp file analysis:
                raise BenchError(32, "Error 32 : Error while trying to assess decompressed size: data may be invalid \n")
            if info == -1:
