            _bench_one_shot_compress(b, level, dict_data)
    best_c = _bench_timed(comp_fn, min_sec)
    comp_speed = (total_src / best_c * 1000.0) if best_c else 0.0
    provisional(comp_total, comp_speed, None)
    def dec_fn():
        for b, cb in zip(blocks, comp_blocks):
            _bench_one_shot_decompress(cb, len(b), dict_data)
    best_d = _bench_timed(dec_fn, min_sec)
    decomp_speed = (total_src / best_d * 1000.0) if best_d else 0.0
    provisional(comp_total, comp_speed, decomp_speed)
    if display >= 2:
        owrite(f"\r{level:2d}#\n")
    elif display == 1:
        ratio = total_src / comp_total if comp_total else 0.0
        owrite(f"-{level:<12d}{comp_total:10d} ({ratio:.3f}) {comp_speed:.2f} MB/s {_bench_speed_str(decomp_speed)} MB/s  {name}\n")

def _bench_frame_decomp_size(data):
    v = _analyze_bytes_for_bench(data)
    return v if isinstance(v, int) and v > 0 else 0
