def _bench_blocks(sample_data):
    """Split sample data (bytes or list of file bytes) into bench blocks."""
    if isinstance(sample_data, list):
        files = sample_data
    else:
        files = [sample_data]
    blocks = []
    if ST.block_size:
        bs = int(ST.block_size)
        for data in files:
            if len(data) == 0:
                blocks.append(b"")
            else:
                for i in range(0, len(data), bs):
                    blocks.append(data[i:i+bs])
    else:
        blocks = list(files)
    return blocks

