def _analyze_bytes_for_bench(data):
    """Return decompressed size, -1 if unknown size, None if invalid."""
    # write through the list analyser logic on the fly using lib frame headers
    lib = _load_lib()
    pos = 0; total = 0; frames = 0
    n = len(data)
    while pos < n:
        if n - pos < 4:
            return None
        magic = int.from_bytes(data[pos:pos+4], "little")
        if 0x184D2A50 <= magic <= 0x184D2A5F:
            if n - pos < 8:
                return None
            fsize = int.from_bytes(data[pos+4:pos+8], "little")
            pos += 8 + fsize
            if pos > n:
                return None
            continue
        if magic != 0xFD2FB528:
            return None
        # find frame size by decompressing this frame stream-wise is heavy;
        # use getFrameContentSize on the remaining buffer: it returns content
        # size of the first frame, and to advance we decompress once.
        buf = ctypes.create_string_buffer(data[pos:], n - pos)
        fcs = lib.ZSTD_getFrameContentSize(ctypes.cast(buf, ctypes.c_void_p), n - pos)
        if fcs == 18446744073709551614:
            return None
        if fcs == 18446744073709551615:
            return -1
        # advance: decompress frame to find its compressed length via stream
        consumed = _bench_frame_consumed(data[pos:])
        if consumed is None:
            return None
        total += int(fcs)
        pos += consumed
        frames += 1
    if frames == 0 and total == 0:
        # only skippable frames -> size 0 (still benchable in reference? treat as 0)
        return 0
    return total

def _bench_frame_consumed(data):
    lib = _load_lib()
    ctx = lib.ZSTD_createDCtx()
    try:
        in_mem = ctypes.create_string_buffer(data, len(data))
        ib = _InBuf(ctypes.cast(in_mem, ctypes.c_void_p), len(data), 0)
        out = ctypes.create_string_buffer(131075)
        while ib.pos < ib.size:
            ob = _OutBuf(ctypes.cast(out, ctypes.c_void_p), len(out), 0)
            r = lib.ZSTD_decompressStream(ctx, ctypes.byref(ob), ctypes.byref(ib))
            if lib.ZSTD_isError(r):
                return None
            if r == 0:
                return ib.pos
        return None
    finally:
        lib.ZSTD_freeDCtx(ctx)

def _bench_level(name, blocks, total_src, level, decomp_only, dict_data, decomp_total, comp_blocks_for_decomp):
    display = ST.display_level
