        def dec_fn():
            for b, ob in zip(comp_blocks_for_decomp, dec_blocks):
                _bench_one_shot_decompress(b, len(ob), dict_data)
        best = _bench_timed(dec_fn, min_sec)
        decomp_speed = (decomp_total / best * 1000.0) if best else 0.0
        provisional(comp_total, 0.0, decomp_speed)
        if display >= 2:
            owrite(f"\r{0:2d}#\n")
        elif display == 1:
            ratio = decomp_total / comp_total if comp_total else 0.0
            owrite(f"-{0:<12d}{comp_total:10d} ({ratio:.3f}) {_bench_speed_str(0.0, quiet_comp=True)} MB/s {_bench_speed_str(decomp_speed)} MB/s  {name}\n")
