    def dec_fn():
        for b, cb in zip(blocks, comp_blocks):
            _bench_one_shot_decompress(cb, len(b), dict_data)
    best_d = _bench_timed(dec_fn, min_sec)
    decomp_speed = (total_src / best_d * 1000.0) if best_d else 0.0
    provisional(comp_total, comp_speed, decomp_speed)
