        owrite(f"\r{level:2d}#\n")
    elif display == 1:
        ratio = total_src / comp_total if comp_total else 0.0
        owrite(f"-{level:<12d}{comp_total:10d} ({ratio:.3f}) {comp_speed:.2f} MB/s {_bench_speed_str(decomp_speed)} MB/s  {name}\n")

