        total = 0
        out_all = bytearray()
        while ib.pos < ib.size:
            ob.pos = 0
            r = lib.ZSTD_decompressStream(ctx, ctypes.byref(ob), ctypes.byref(ib))
            if lib.ZSTD_isError(r):
                raise BenchError(1, f"Error : {lib_error_message(r)} \n")
            out_all += out.raw[:ob.pos]
            if r == 0:
                lib.ZSTD_DCtx_reset(ctx, 1)
        return bytes(out_all)
    finally:
        lib.ZSTD_freeDCtx(ctx)

def _bench_timed(fn, min_seconds):
    """Run fn repeatedly; return best ns per call."""
    best = None
    total = 0
    count = 1
    rounds = 0
    while True:
        start = time.perf_counter_ns()
        for _ in range(count):
            fn()
        elapsed = time.perf_counter_ns() - start
        if elapsed <= 0:
            elapsed = 1
        per = elapsed / count
        if best is None or per < best:
            best = per
        total += elapsed
        rounds += 1
        if min_seconds <= 0:
            break
        if total >= min_seconds * 1000000000:
            break
        # scale count toward the requested duration
        target = min_seconds * 1000000000
        if elapsed > 0:
            new_count = int(count * target / elapsed) + 1
        else:
            new_count = count * 10
        if new_count <= count:
            new_count = count + 1
        count = new_count
        if rounds > 10000:
            break
    return best

def _generate_synthetic():
    if ST.compressibility is None:
        # "Lorem ipsum" sample: pseudo-natural text, deterministic.
        words = ("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod "
                 "tempor incididunt ut labore et dolore magna aliqua enim ad minim veniam "
                 "quis nostrud exercitation ullamco laboris nisi aliquip ex ea commodo "
                 "consequat duis aute irure in reprehenderit voluptate velit esse cillum "
                 "fugiat nulla pariatur excepteur sint occaecat cupidatat non proident "
                 "sunt culpa qui officia deserunt mollit anim id est laborum").split()
        out = bytearray()
        seed = 0x9E3779B9
        def rnd():
            nonlocal seed
            seed ^= (seed << 13) & 0xFFFFFFFF
            seed ^= seed >> 17
            seed ^= (seed << 5) & 0xFFFFFFFF
            return seed & 0xFFFFFFFF
        while len(out) < 10000000:
            nwords = 4 + rnd() % 10
            sentence = []
            for i in range(nwords):
                w = words[rnd() % len(words)]
                sentence.append(w)
            s = " ".join(sentence).capitalize() + ". "
            out += s.encode()
        return bytes(out[:10000000]), "Lorem ipsum"
    pct = int(ST.compressibility)
    # deterministic compressible data
    out = bytearray()
    seed = 0x1234567
    def rndbyte():
        nonlocal seed
        seed = (seed * 1103515245 + 12345) & 0x7FFFFFFF
        return (seed >> 8) & 0xFF
    pattern = bytes(range(256))
    if pct >= 100:
        while len(out) < 10000000:
            out += pattern
        return bytes(out[:10000000]), f"Synthetic {pct}%"
    if pct <= 0:
        return bytes(rndbyte() for _ in range(10000000)), f"Synthetic {pct}%"
    # interleaved pattern / random in small runs
    pos = 0
    while len(out) < 10000000:
        run = 50 + rndbyte()
        if (rndbyte() % 100) < pct:
            seg = (pattern[pos % 256:] + pattern * 2)[:run]
            out += seg; pos += run
        else:
            out += bytes(rndbyte() for _ in range(run))
    return bytes(out[:10000000]), f"Synthetic {pct}%"

