def _analyze_bytes_for_bench(data):
    """Return decompressed size, -1 if unknown size, None if invalid."""
    # write through the list analyser logic on the fly using lib frame headers
    lib = _load_lib()
    pos = 0; total = 0; frames = 0
    n = len(data)
    while pos < n:
        if n - pos < 4:
            return None
        magic = int.from_bytes(data[pos:pos+4], "little")
        if 0x184D2A50 <= magic <= 0x184D2A5F:
            if n - pos < 8:
                return None
            fsize = int.from_bytes(data[pos+4:pos+8], "little")
            pos += 8 + fsize
            if pos > n:
                return None
            continue
        if magic != 0xFD2FB528:
            return None
        # find frame size by decompressing this frame stream-wise is heavy;
        # use getFrameContentSize on the remaining buffer: it returns content
        # size of the first frame, and to advance we decompress once.
        buf = ctypes.create_string_buffer(data[pos:], n - pos)
        fcs = lib.ZSTD_getFrameContentSize(ctypes.cast(buf, ctypes.c_void_p), n - pos)
        if fcs == 18446744073709551614:
            return None
        if fcs == 18446744073709551615:
            return -1
        # advance: decompress frame to find its compressed length via stream
        consumed = _bench_frame_consumed(data[pos:])
        if consumed is None:
            return None
        total += int(fcs)
        pos += consumed
        frames += 1
    if frames == 0 and total == 0:
        # only skippable frames -> size 0 (still benchable in reference? treat as 0)
        return 0
    return total

def _bench_frame_consumed(data):
    lib = _load_lib()
    ctx = lib.ZSTD_createDCtx()
    try:
        in_mem = ctypes.create_string_buffer(data, len(data))
        ib = _InBuf(ctypes.cast(in_mem, ctypes.c_void_p), len(data), 0)
        out = ctypes.create_string_buffer(131075)
        while ib.pos < ib.size:
            ob = _OutBuf(ctypes.cast(out, ctypes.c_void_p), len(out), 0)
            r = lib.ZSTD_decompressStream(ctx, ctypes.byref(ob), ctypes.byref(ib))
            if lib.ZSTD_isError(r):
                return None
            if r == 0:
                return ib.pos
        return None
    finally:
        lib.ZSTD_freeDCtx(ctx)

def _bench_level(name, blocks, total_src, level, decomp_only, dict_data, decomp_total, comp_blocks_for_decomp):
    display = ST.display_level
    name_field = name
    def provisional(comp_size=None, comp_speed=None, decomp_speed=None, spinner="|-"):
        if display < 2:
            return
        src_display = decomp_total if decomp_only else total_src
        line = f" {spinner}{name_field:<18s} : {src_display:10d} -> "
        if comp_size is not None:
            ratio = (src_display / comp_size) if comp_size else 0.0
            line += f"{comp_size:10d} (x{_bench_ratio_str(ratio)}), {_bench_speed_str(comp_speed)} MB/s"
            if decomp_speed is None:
                line += " "
            else:
                line += f", {_bench_speed_str(decomp_speed)} MB/s"
        owrite(b"\r" + fsb(line))
    min_sec = int(ST.bench_seconds)
    if decomp_only:
        comp_total = sum(len(b) for b in comp_blocks_for_decomp)
        provisional()
        # decompress bench
        outsizes = []
        # prepare decompressed outputs once to size buffers
        dec_blocks = [_bench_one_shot_decompress(b, _bench_frame_decomp_size(b) or 0, dict_data) for b in comp_blocks_for_decomp]
        def dec_fn():
            for b, ob in zip(comp_blocks_for_decomp, dec_blocks):
                _bench_one_shot_decompress(b, len(ob), dict_data)
        best = _bench_timed(dec_fn, min_sec)
        decomp_speed = (decomp_total / best * 1000.0) if best else 0.0
        provisional(comp_total, 0.0, decomp_speed)
        if display >= 2:
            owrite(f"\r{0:2d}#\n")
        elif display == 1:
            ratio = decomp_total / comp_total if comp_total else 0.0
            owrite(f"-{0:<12d}{comp_total:10d} ({ratio:.3f}) {_bench_speed_str(0.0, quiet_comp=True)} MB/s {_bench_speed_str(decomp_speed)} MB/s  {name}\n")
        return
    # compression bench
    comp_blocks = [_bench_one_shot_compress(b, level, dict_data) for b in blocks]
    comp_total = sum(len(b) for b in comp_blocks)
    provisional()
    def comp_fn():
        for b in blocks:
            _bench_one_shot_compress(b, level, dict_data)
    best_c = _bench_timed(comp_fn, min_sec)
    comp_speed = (total_src / best_c * 1000.0) if best_c else 0.0
    provisional(comp_total, comp_speed, None)
    def dec_fn():
        for b, cb in zip(blocks, comp_blocks):
            _bench_one_shot_decompress(cb, len(b), dict_data)
    best_d = _bench_timed(dec_fn, min_sec)
    decomp_speed = (total_src / best_d * 1000.0) if best_d else 0.0
    provisional(comp_total, comp_speed, decomp_speed)
    if display >= 2:
        owrite(f"\r{level:2d}#\n")
    elif display == 1:
        ratio = total_src / comp_total if comp_total else 0.0
        owrite(f"-{level:<12d}{comp_total:10d} ({ratio:.3f}) {comp_speed:.2f} MB/s {_bench_speed_str(decomp_speed)} MB/s  {name}\n")

def _bench_frame_decomp_size(data):
    v = _analyze_bytes_for_bench(data)
    return v if isinstance(v, int) and v > 0 else 0
