  o=comp(1,stream,131072,order);print(stream,order,len(o),hashlib.sha256(o).hexdigest()[:10],o==orig)
# chunk small
o=comp(1,True,4096,"hint-before");print("chunk4096",len(o),hashlib.sha256(o).hexdigest()[:10],o==orig)
